-- Herodotus Book 2 + Samuels: a course with one chapter per reading (plus a mix), for live team games.
-- Run in Supabase: SQL Editor -> New query -> paste -> Run. Safe to run again (it replaces these chapters).
do $$
declare cid uuid;
begin
  insert into courses (slug, code, title, description, instructions, sort, published, kind, visibility)
  values ('herodotus-samuels', 'Herodotus & Samuels', 'Herodotus Book 2 and Samuels (Mon 11/2)',
          'Herodotus 2.1–2.64 and 2.99–2.122, and Tristan Samuels, "Herodotus and the Black Body" (2015). Each reading is its own chapter: open one and press Play live to run a team game.',
          '', 5, true, 'class', 'public')
  on conflict (slug) do update set code = excluded.code, title = excluded.title, description = excluded.description, published = true
  returning id into cid;
  delete from chapters where course_id = cid and professor_id is null and number between 1 and 4;
  insert into chapters (course_id, professor_id, number, title, instructions, content, settings, published)
  values (cid, null, 1, 'Herodotus 2.1–2.64: The Land, the Nile, and the Gods', '', $j${"summary": "Herodotus opens his account of Egypt: Psammetichos' language experiment, Egypt as the 'gift of the river', the Ionians' mistaken map, the theories of the Nile flood and its sources, Egypt's 'upside-down' customs, sacrifice and animal taboos, and his argument that Greek gods, rites, oracles and festivals came from Egypt.", "sections": [{"id": "sec-obflauw2", "title": "The land and the Nile (2.1–2.34)", "blurb": "Bekos, the gift of the river, flood theories, sources"}, {"id": "sec-wry6nv5g", "title": "Upside-down customs (2.35–2.48)", "blurb": "Daily life, purity, sacrifice, sacred animals"}, {"id": "sec-16tnmz7r", "title": "Gods, oracles, festivals (2.49–2.64)", "blurb": "Melampous, Pelasgians, Dodona's doves, festivals"}], "terms": [{"id": "xttgsjvo", "term": "Psammetichos (experiment)", "definition": "Egyptian king who had two newborns raised by a shepherd with no one speaking near them, to learn which people was oldest (2.2).", "section": "sec-obflauw2"}, {"id": "mg3ld2wd", "term": "bekos", "definition": "The children's first word. It means 'bread' in Phrygian, so the Egyptians conceded the Phrygians were older than themselves (2.2).", "section": "sec-obflauw2"}, {"id": "x3vu51ce", "term": "Priests of Hephaistos at Memphis", "definition": "Herodotus' main source for the bekos story; he also checked their accounts at Thebes and Heliopolis (2.2–2.3).", "section": "sec-obflauw2"}, {"id": "a9sk6kj8", "term": "Egyptian calendar", "definition": "12 months of 30 days plus 5 extra days a year. Herodotus thinks it wiser than the Greek system of an extra month every other year (2.4).", "section": "sec-obflauw2"}, {"id": "ux2jws52", "term": "Min", "definition": "The first king of Egypt, according to the priests. In his day all Egypt except the district of Thebes was swamp (2.4).", "section": "sec-obflauw2"}, {"id": "nzz01g1e", "term": "'Gift of the river'", "definition": "Herodotus' description of the Egypt Greeks sail to: land deposited by the Nile (2.5).", "section": "sec-obflauw2"}, {"id": "sm189h61", "term": "schoinos", "definition": "An Egyptian unit of distance ('rope') equal to 60 stades; Herodotus gives the coast as 60 schoinoi, about 397 miles (2.6).", "section": "sec-obflauw2"}, {"id": "ilc0viax", "term": "Ionian view of Egypt", "definition": "That Egypt is only the Delta and the world has three parts. Herodotus says the Delta would then be a fourth part, and calls the view absurd (2.15–2.16).", "section": "sec-obflauw2"}, {"id": "qrz0mvt6", "term": "Oracle of Ammon (on who is Egyptian)", "definition": "Told the people of Mareia and Apis, who wanted to eat cow meat, that Egypt is all land the Nile floods and Egyptians are those below Elephantine who drink its water (2.18).", "section": "sec-obflauw2"}, {"id": "mp6vvpdn", "term": "Etesian winds theory", "definition": "Greek idea that the summer north winds hold the Nile back and cause the flood. Refuted: the Nile floods even when they don't blow (2.20).", "section": "sec-obflauw2"}, {"id": "xfpa2o2w", "term": "Ocean theory", "definition": "Greek idea that the Nile flows from Ocean, which surrounds the world. Herodotus says it can't be refuted because it's in the unknown, and Ocean was likely invented by Homer or earlier poets (2.21, 2.23).", "section": "sec-obflauw2"}, {"id": "gid3y0aj", "term": "Melting snow theory", "definition": "The 'most plausible' but 'most erroneous' theory, per Herodotus: the Nile flows from the hottest lands, where winds are warm and people are black from the sun (2.22).", "section": "sec-obflauw2"}, {"id": "7jmhcyfz", "term": "Herodotus' sun theory", "definition": "In winter storms drive the sun south over Libya, where it draws water up from the Nile, so the Nile alone runs low in winter (2.24–2.26).", "section": "sec-obflauw2"}, {"id": "fp53ajct", "term": "Scribe of Athena's treasury at Sais", "definition": "The only person who claimed to know the Nile's sources: bottomless springs between the mountains Krophi and Mophi. Herodotus thought he was joking (2.28).", "section": "sec-obflauw2"}, {"id": "tmnw1lm5", "term": "Elephantine", "definition": "City at the First Cataract. Herodotus says he saw this far himself; beyond it he relies on hearsay (2.29).", "section": "sec-obflauw2"}, {"id": "cfo4j2kn", "term": "Meroe", "definition": "The metropolis of the Ethiopians, where only Zeus and Dionysos are worshiped and an oracle of Zeus decides their wars (2.29).", "section": "sec-obflauw2"}, {"id": "frn080ko", "term": "The Deserters (Asmach)", "definition": "240,000 Egyptian soldiers who left King Psammetichos for Ethiopia after three years on garrison duty without relief (2.30).", "section": "sec-obflauw2"}, {"id": "my19ou91", "term": "Nasamonian youths", "definition": "Five young Libyans who crossed the desert westward and were captured by small, black-skinned people living by a river with crocodiles (2.32).", "section": "sec-obflauw2"}, {"id": "v36tevbb", "term": "Ister (Danube)", "definition": "Europe's great river. Herodotus argues the Nile's course through Libya equals the Ister's course through Europe (2.33–2.34).", "section": "sec-obflauw2"}, {"id": "snof7p26", "term": "Egyptian 'opposite' customs", "definition": "Women sell in the market while men weave at home; men carry loads on their heads, women on their shoulders (2.35).", "section": "sec-wry6nv5g"}, {"id": "1x285i0j", "term": "Egyptian writing", "definition": "Written right to left, with two scripts, called 'sacred' and 'public' (2.36).", "section": "sec-wry6nv5g"}, {"id": "vpygbzs8", "term": "Egyptian priests (purity)", "definition": "Shave their whole bodies every other day, wear only linen and papyrus sandals, bathe twice a day and twice a night, and may not eat fish (2.37).", "section": "sec-wry6nv5g"}, {"id": "2kws8nto", "term": "Inspection of sacrificial bulls", "definition": "Bulls belong to Epaphos (Apis); one black hair makes a bull unclean. A clean bull is sealed with papyrus and clay; sacrificing an unmarked one means death (2.38).", "section": "sec-wry6nv5g"}, {"id": "flhalukn", "term": "Curses on the bull's head", "definition": "Egyptians curse the head so any evil falls on it, then sell it to Greeks or throw it in the river; no Egyptian eats an animal's head (2.39).", "section": "sec-wry6nv5g"}, {"id": "6ou8794y", "term": "Isis and cows", "definition": "Female cattle are sacred to Isis, whose statue has cow's horns like the Greek Io; Egyptians won't kiss a Greek or use his knife because Greeks eat cows (2.41).", "section": "sec-wry6nv5g"}, {"id": "agbv16il", "term": "Atarbechis", "definition": "City on the island of Prosopitis that sends barges to collect buried bulls' bones from across Egypt (2.41).", "section": "sec-wry6nv5g"}, {"id": "fz3k7l8i", "term": "Ram-headed Zeus (Ammon)", "definition": "Zeus showed himself to Herakles wrapped in a ram's fleece, so Thebans don't sacrifice rams and the Ammonians took their name from Ammon (2.42).", "section": "sec-wry6nv5g"}, {"id": "2dhz24nq", "term": "Egyptian Herakles", "definition": "An ancient god, one of the twelve. Herodotus sails to Tyre and Thasos and concludes Herakles is far older than the Greek son of Amphitryon (2.43–2.44).", "section": "sec-wry6nv5g"}, {"id": "f7bzj614", "term": "Mendes", "definition": "Egyptian name for both Pan and the most honored he-goat; the Mendesians don't sacrifice goats (2.46).", "section": "sec-wry6nv5g"}, {"id": "7448oo0u", "term": "Swineherds", "definition": "The only native Egyptians barred from every sanctuary; no one marries them, so they marry among themselves (2.47).", "section": "sec-wry6nv5g"}, {"id": "41nxm7xp", "term": "Melampous", "definition": "The Greek who taught the Hellenes the name of Dionysos, his sacrifice and the phallic procession, using what he learned from Egypt (2.49).", "section": "sec-wry6nv5g"}, {"id": "j0yim2cb", "term": "Names of the gods", "definition": "Herodotus says almost all came to Hellas from Egypt, except Poseidon (from Libya), the Dioskouroi, Hera, Histia, Themis, the Graces and the Nereids (2.50).", "section": "sec-16tnmz7r"}, {"id": "ssrj4ln4", "term": "Pelasgians", "definition": "Thought to be Greece's original inhabitants. They taught the Athenians to make statues of Hermes with an erect phallus and learned the gods' names from Egypt (2.51–2.52).", "section": "sec-16tnmz7r"}, {"id": "hd2ty94f", "term": "Oracle of Dodona", "definition": "Thought to be the oldest Greek oracle; it told the Pelasgians to use the gods' names that came from the barbarians (2.52).", "section": "sec-16tnmz7r"}, {"id": "y4rq8aim", "term": "Hesiod and Homer", "definition": "Poets who, Herodotus says, lived no more than 400 years before him and gave the Greeks the theogony, the gods' epithets, honors and looks (2.53).", "section": "sec-16tnmz7r"}, {"id": "1z1rb3ep", "term": "Two black doves", "definition": "Dodona's story: doves flew from Egyptian Thebes, one founding the oracle at Dodona and one Ammon's in Libya (2.55).", "section": "sec-16tnmz7r"}, {"id": "1lazih01", "term": "Herodotus' reading of the doves", "definition": "The 'dove' was an Egyptian woman sold by Phoenicians; her foreign speech sounded like a bird's, and calling her black shows she was Egyptian (2.56–2.57).", "section": "sec-16tnmz7r"}, {"id": "zzffxzac", "term": "Boubastis festival", "definition": "Egypt's most popular festival, for Artemis; up to 700,000 people come by barge and drink more wine than all year (2.59–2.60).", "section": "sec-16tnmz7r"}, {"id": "6j7rxhx5", "term": "Feast of the Burning Lamps", "definition": "Festival at Sais for Athena, when lamps burn all night across Egypt (2.62).", "section": "sec-16tnmz7r"}, {"id": "b3s3j8l5", "term": "Papremis festival", "definition": "Festival for Ares with a club fight between priests and men fulfilling vows, said to recall Ares forcing his way in to his mother (2.63).", "section": "sec-16tnmz7r"}], "questions": [{"id": "4d81ig1c", "prompt": "What did Psammetichos' experiment with two newborn children conclude?", "choices": ["The Ethiopians are the oldest people", "All languages descend from Greek", "The Phrygians are older than the Egyptians", "The Egyptians are the oldest people"], "answer": 2, "explanation": "The children said 'bekos', Phrygian for bread, so the Egyptians accepted that the Phrygians were older than themselves (2.2).", "difficulty": "easy", "section": "sec-obflauw2"}, {"id": "knx5p3h5", "prompt": "Who raised the children in Psammetichos' experiment, and how were they fed?", "choices": ["Women whose tongues were cut out, on milk", "The king's own household, on honey", "A shepherd, on goats' milk", "Priests, on bread"], "answer": 2, "explanation": "A shepherd kept them in a secluded hut and brought in goats to feed them. The tongue-cutting version is a 'silly' Greek story (2.2).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "otesgc80", "prompt": "Herodotus calls the Egypt that the Greeks sail to…", "choices": ["the land of the pharaohs", "the mother of nations", "the floor of the sea", "the gift of the river"], "answer": 3, "explanation": "Land deposited by the Nile is 'the gift of the river' to the Egyptians (2.5).", "difficulty": "easy", "section": "sec-obflauw2"}, {"id": "tg6xxqzj", "prompt": "Why does Herodotus think the Egyptian calendar is better than the Greek one?", "choices": ["It follows the moon exactly", "It starts with the Nile flood", "It has thirteen months", "Twelve 30-day months plus five extra days keep the seasons in place"], "answer": 3, "explanation": "The Greeks add an extra month every other year; the Egyptians add five days a year, so their seasons return at the same time (2.4).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "86eldv86", "prompt": "What evidence does Herodotus give that Egypt was built up from river mud?", "choices": ["Seashells on the mountains and salt eating at the pyramids", "Old maps kept by the priests", "Fish fossils in the temples", "Greek sailors' logbooks"], "answer": 0, "explanation": "He cites the Delta jutting out, seashells on the mountains, salt damaging the pyramids, and the black crumbly soil (2.12).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "9tasi5mu", "prompt": "What did the Egyptians predict would happen to the Greeks someday?", "choices": ["A drought would starve them, since their crops depend on rain from Zeus", "Their soil would turn to salt", "Their rivers would flood their cities", "The Persians would conquer them"], "answer": 0, "explanation": "Greek land is watered only by rain, so if Zeus sends drought instead the Greeks would starve. Herodotus warns Egyptians below Memphis could face the same if their land keeps rising (2.13–2.14).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "4g4cbs47", "prompt": "How do farmers below Memphis plant and thresh their grain, according to Herodotus?", "choices": ["They let pigs tread the seed in and thresh it", "Slaves dig with hoes", "They throw seed into the flood", "With oxen and plows"], "answer": 0, "explanation": "When the river recedes each man sows his field and turns pigs onto it to tread the seed in, then threshes with pigs too (2.14).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "2we7tsye", "prompt": "Which view of Egypt does Herodotus reject?", "choices": ["The oracle of Ammon's definition", "The Ionian view that Egypt is only the Delta", "That Egypt reaches to Elephantine", "That Egypt is all land the Nile floods"], "answer": 1, "explanation": "If Egypt were just the recently formed Delta, the Egyptians couldn't have thought themselves the first people. He defines Egypt as land inhabited by Egyptians (2.15–2.17).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "g2shkoje", "prompt": "Why did the people of Mareia and Apis ask the oracle of Ammon to declare them non-Egyptian?", "choices": ["So they could eat cow meat", "To avoid paying taxes", "To marry Libyans", "To avoid military service"], "answer": 0, "explanation": "They disliked the rule against eating cows. The oracle said all who live below Elephantine and drink the Nile's water are Egyptians (2.18).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "5bowhj36", "prompt": "When does the Nile begin to flood, according to Herodotus?", "choices": ["At the summer solstice, for about 100 days", "At the spring equinox", "In midwinter", "After the Etesian winds stop"], "answer": 0, "explanation": "It floods from the summer solstice for 100 days, then stays low all winter, the opposite of other rivers (2.19).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "6zw1bzyk", "prompt": "How does Herodotus refute the Etesian winds theory of the flood?", "choices": ["Priests told him it was false", "The winds blow from the south", "The Etesians only blow in winter", "The Nile floods even when the Etesians don't blow, and other rivers facing those winds don't flood"], "answer": 3, "explanation": "He gives both arguments in 2.20.", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "y13esqjb", "prompt": "Which flood theory does Herodotus call the most plausible but most wrong?", "choices": ["The Etesian winds", "The Nile flows from Ocean", "The sun", "Melting snow"], "answer": 3, "explanation": "Snow is impossible: the Nile comes from the hottest lands, where winds are warm, there's no rain or ice, and people are black from the sun (2.22).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "pw2vlfpk", "prompt": "What is Herodotus' own explanation for why the Nile runs low in winter?", "choices": ["Snow freezes its sources", "The Etesian winds push it back", "The winter sun over Libya draws the Nile's water up", "Winter rain is caught in lakes"], "answer": 2, "explanation": "Storms drive the sun south in winter; it draws water from the Nile, which alone suffers evaporation in winter (2.24–2.25).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "wsein3wt", "prompt": "Who claimed to know the sources of the Nile, and what did Herodotus think?", "choices": ["Etearchos; he agreed completely", "Priests at Memphis; he believed them", "A scribe of Athena's treasury at Sais; Herodotus thought he was joking", "The Nasamonians; he called them liars"], "answer": 2, "explanation": "The scribe spoke of bottomless springs between Krophi and Mophi (2.28).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "1rxq2utc", "prompt": "How far up the Nile does Herodotus say he traveled to see for himself?", "choices": ["Thebes", "Memphis", "Elephantine", "Meroe"], "answer": 2, "explanation": "He went as far as Elephantine; everything beyond came from hearsay (2.29).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "5g0c0795", "prompt": "Why did the 240,000 'Deserters' leave Psammetichos for Ethiopia?", "choices": ["Psammetichos took their land", "No one relieved them from garrison duty for three years", "They were defeated in battle", "An oracle ordered them"], "answer": 1, "explanation": "After three years without relief they revolted and went to Ethiopia, where they made the Ethiopians more civilized (2.30).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "i1as95uk", "prompt": "What did the Nasamonian youths find beyond the Libyan desert?", "choices": ["A city of giants by a lake", "Small black-skinned people by a river with crocodiles flowing east", "A Greek colony", "The source of the Nile in two mountains"], "answer": 1, "explanation": "Herodotus and Etearchos think the river was the Nile (2.32–2.33).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "pg1a2m87", "prompt": "Which river does Herodotus say mirrors the Nile in length and course?", "choices": ["Ister (Danube)", "Maeander", "Phasis", "Achelous"], "answer": 0, "explanation": "The Ister cuts Europe in half just as the Nile cuts Libya in half (2.33–2.34).", "difficulty": "medium", "section": "sec-obflauw2"}, {"id": "bmxdj198", "prompt": "Which of these is one of the Egyptian 'opposite' customs Herodotus lists?", "choices": ["Men sell in the market, women weave", "Both men and women weave", "Only slaves go to market", "Women sell in the market, men weave at home"], "answer": 3, "explanation": "Herodotus says Egyptian customs are mostly the opposite of others' (2.35).", "difficulty": "easy", "section": "sec-wry6nv5g"}, {"id": "qyajxq89", "prompt": "How do Egyptian men and women carry loads, according to Herodotus?", "choices": ["Only donkeys carry loads", "Men on shoulders, women on heads", "Men on heads, women on shoulders", "Both on their backs"], "answer": 2, "explanation": "Another reversal from 2.35.", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "g7y19tom", "prompt": "What do Egyptians do with their hair when someone dies?", "choices": ["Cut it and burn it", "Shave it off", "Let it grow on head and chin", "Dye it black"], "answer": 2, "explanation": "Elsewhere mourners cut their hair; Egyptians, who are usually shaved, let it grow (2.36).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "owm6fk0p", "prompt": "Which food may Egyptian priests NOT eat?", "choices": ["Fish", "Beef", "Bread", "Goose"], "answer": 0, "explanation": "Priests receive beef, goose and wine but may not even taste fish, and can't stand the sight of beans (2.37).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "2a9ln5yq", "prompt": "What makes a bull unclean for sacrifice?", "choices": ["A single black hair", "Having been born at night", "A white spot on its tail", "Being older than two"], "answer": 0, "explanation": "One black hair disqualifies it; a clean bull is sealed and marked, and sacrificing an unmarked one is punished by death (2.38).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "6swf7386", "prompt": "What happens to the head of a sacrificed bull?", "choices": ["It is cursed, then sold to Greeks or thrown into the river", "The priests eat it", "It is buried in the temple", "It is placed on the altar"], "answer": 0, "explanation": "The curses send any coming evil onto the head; no Egyptian will eat an animal's head (2.39).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "4kw310iu", "prompt": "Why won't an Egyptian kiss a Greek man or use his knife?", "choices": ["Greeks eat pigs", "Greeks are uncircumcised", "Greeks don't shave", "Greeks eat cows, which are sacred to Isis"], "answer": 3, "explanation": "Cows are sacred to Isis, so Egyptians avoid Greeks' knives, skewers and pots (2.41).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "hcn647bp", "prompt": "Why do the Thebans not sacrifice rams?", "choices": ["An oracle forbade it", "Rams belong to Isis", "Rams are too expensive", "Zeus showed himself to Herakles wearing a ram's fleece and head"], "answer": 3, "explanation": "So the Egyptians make Zeus (Ammon) ram-headed and treat rams as sacred (2.42).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "jhwahv0f", "prompt": "Why did Herodotus sail to Tyre and Thasos?", "choices": ["To learn how old Herakles is", "To find the Nile's source", "To see the Deserters", "To buy papyrus"], "answer": 0, "explanation": "Both sanctuaries of Herakles were far older than the Greek Herakles son of Amphitryon (2.44).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "de8ovlcz", "prompt": "Why does Herodotus reject the Greek story that Egyptians tried to sacrifice Herakles?", "choices": ["Herakles never went to Egypt", "Herakles was Egyptian", "The story came from Persians", "Egyptians may not even sacrifice most animals, let alone humans"], "answer": 3, "explanation": "He also asks how one man could kill thousands at once (2.45).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "jxec9rix", "prompt": "Which Egyptians are barred from every sanctuary?", "choices": ["Foreigners", "Swineherds", "Fishermen", "Scribes"], "answer": 1, "explanation": "Pigs are unclean; swineherds can't enter temples and must marry among themselves (2.47).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "fx1r7ree", "prompt": "Who taught the Greeks the name of Dionysos and the phallic procession?", "choices": ["Melampous", "Kadmos", "Pythagoras", "Homer"], "answer": 0, "explanation": "Melampous learned it from Egypt, probably through Kadmos of Tyre (2.49).", "difficulty": "medium", "section": "sec-wry6nv5g"}, {"id": "7xbckqmi", "prompt": "Where does Herodotus say Poseidon's name came to the Greeks from?", "choices": ["Egypt", "Libya", "Thrace", "Phoenicia"], "answer": 1, "explanation": "The Libyans alone have always honored Poseidon (2.50).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "o7urdg1o", "prompt": "From whom did the Athenians learn to make statues of Hermes with an erect phallus?", "choices": ["The Egyptians", "The Libyans", "The Pelasgians", "The Phoenicians"], "answer": 2, "explanation": "The Pelasgians, who also lived on Samothrace (2.51).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "ox1ouvze", "prompt": "What did the oracle at Dodona tell the Pelasgians about the gods' names from Egypt?", "choices": ["Reject them", "Use them", "Ask Ammon", "Use only Zeus"], "answer": 1, "explanation": "Dodona, thought to be the oldest Greek oracle, approved them (2.52).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "rufpm0td", "prompt": "According to Herodotus, who gave the Greeks the theogony and the gods' appearances?", "choices": ["Orpheus and Musaeus", "Melampous", "Hesiod and Homer, no more than 400 years before his time", "The Pelasgians"], "answer": 2, "explanation": "He believes the poets said to be earlier actually lived later (2.53).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "om04qzwx", "prompt": "In the Dodona priestesses' story, what founded the oracles of Dodona and Ammon?", "choices": ["Two black doves from Egyptian Thebes", "Herakles", "Two eagles from Zeus", "Two Phoenician priests"], "answer": 0, "explanation": "One dove went to Dodona and spoke with a human voice; the other went to Libya (2.55).", "difficulty": "easy", "section": "sec-16tnmz7r"}, {"id": "nzbj4u19", "prompt": "How does Herodotus explain the 'dove' that spoke at Dodona?", "choices": ["It was a Greek poetic image only", "It was a real talking bird", "It was a foreign woman whose speech sounded like a bird's, and 'black' shows she was Egyptian", "It was a priest in disguise"], "answer": 2, "explanation": "He thinks she later learned Greek and 'spoke with a human voice' (2.57).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "u7lhi674", "prompt": "Which is Egypt's most popular festival?", "choices": ["Artemis at Boubastis", "Ares at Papremis", "Athena at Sais", "Isis at Bousiris"], "answer": 0, "explanation": "Up to 700,000 men and women gather at Boubastis (2.59–2.60).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "pi9t9wmz", "prompt": "What happens at the festival of Ares at Papremis?", "choices": ["A club fight at the sanctuary entrance", "A boat race", "Lamps burn all night", "Women mock other towns from barges"], "answer": 0, "explanation": "Priests and vow-fulfillers fight with wooden clubs; Herodotus thinks many die, though the Egyptians deny it (2.63).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "2yt6eatk", "prompt": "The Feast of the Burning Lamps is held at…", "choices": ["Sais", "Memphis", "Bouto", "Heliopolis"], "answer": 0, "explanation": "The festival at Sais honors Athena; lamps burn all night all over Egypt (2.62).", "difficulty": "medium", "section": "sec-16tnmz7r"}, {"id": "o80pc3t3", "prompt": "What religious rule do Egyptians and Greeks share, according to Herodotus?", "choices": ["No festivals at night", "No sacrifice of goats", "No intercourse in sanctuaries, or entering unwashed after it", "No eating beans"], "answer": 2, "explanation": "Most other peoples, he says, don't keep this rule (2.64).", "difficulty": "medium", "section": "sec-16tnmz7r"}], "entries": []}$j$::jsonb, $j${"modes": ["learn", "flashcards", "quiz", "match", "rush"], "questionCount": 10, "rushSeconds": 60, "matchPairs": 6, "shuffle": true, "showExplanations": true, "requireFlashcardsFirst": false, "v": 2}$j$::jsonb, true);
  insert into chapters (course_id, professor_id, number, title, instructions, content, settings, published)
  values (cid, null, 2, 'Herodotus 2.99–2.122: Kings of Egypt, from Min to Rhampsinitos', '', $j${"summary": "Herodotus switches from what he saw to what the priests told him: Min founds Memphis, Nitokris takes revenge, Sesostris conquers Asia and (he argues) leaves the Colchians behind, Pheros is blinded, Proteus keeps Helen while the Greeks besiege Troy, and Rhampsinitos is outwitted by a master thief.", "sections": [{"id": "sec-nz6w2rzr", "title": "Min to Sesostris (2.99–2.110)", "blurb": "Memphis, Nitokris, Sesostris, the Colchians"}, {"id": "sec-zi032pmo", "title": "Pheros, Proteus and Helen (2.111–2.120)", "blurb": "Blindness, Helen in Egypt, Homer, Troy"}, {"id": "sec-sk9gs0we", "title": "Rhampsinitos (2.121–2.122)", "blurb": "The treasury thief and the dice game with Demeter"}], "terms": [{"id": "go9xqscj", "term": "The turn at 2.99", "definition": "Up to here Herodotus relied on his own observation and research; from here he reports what the Egyptians told him, adding his own observations at times.", "section": "sec-nz6w2rzr"}, {"id": "37l7o9db", "term": "Min (founding Memphis)", "definition": "The first king. He dammed the Nile about 11 miles south of Memphis, moved it into a new channel, founded Memphis on the dried land and built the sanctuary of Hephaistos (2.99).", "section": "sec-nz6w2rzr"}, {"id": "1sqsipht", "term": "330 kings", "definition": "The kings the priests read from a papyrus roll after Min: all Egyptian men except 18 Ethiopians and one native woman (2.100).", "section": "sec-nz6w2rzr"}, {"id": "3efh913l", "term": "Nitokris", "definition": "The one queen. She avenged her murdered brother by inviting the guilty to a feast in an underground chamber and flooding it, then threw herself into a room full of ashes (2.100).", "section": "sec-nz6w2rzr"}, {"id": "if30riov", "term": "Moeris", "definition": "The last of the unremarkable kings: built the north gateway of Hephaistos' sanctuary and dug a lake with pyramids in it (2.101).", "section": "sec-nz6w2rzr"}, {"id": "p8dnlgld", "term": "Sesostris", "definition": "Conquering king who sailed from the Arabian Gulf, then marched through Asia into Europe, beating the Scythians and Thracians (2.102–2.103).", "section": "sec-nz6w2rzr"}, {"id": "aht1c4vh", "term": "Sesostris' pillars", "definition": "Inscribed with his name and country. For peoples who gave up without a fight he added female genitals to mark their cowardice (2.102).", "section": "sec-nz6w2rzr"}, {"id": "4oi0abc7", "term": "Colchians", "definition": "People by the Phasis River whom Herodotus calls Egyptians left behind by Sesostris' army (2.103–2.104).", "section": "sec-nz6w2rzr"}, {"id": "esg1vk3f", "term": "2.104 evidence", "definition": "Black skin and woolly (kinky) hair, which he says proves nothing alone, and 'more' that only Colchians, Egyptians and Ethiopians have circumcised from the earliest times (2.104).", "section": "sec-nz6w2rzr"}, {"id": "fhcj4yfz", "term": "Linen of Colchis", "definition": "Made by the same method as Egyptian linen; the Greeks call it 'Sardonian' (2.105).", "section": "sec-nz6w2rzr"}, {"id": "ebye6zlk", "term": "Rock reliefs in Ionia", "definition": "Two carved figures with spear and bow on the roads Ephesus–Phocaea and Sardis–Smyrna, inscribed 'I acquired this land by the strength of my shoulders'. Some say Memnon; Herodotus says Sesostris (2.106).", "section": "sec-nz6w2rzr"}, {"id": "7b87wo51", "term": "The fire at Daphnai", "definition": "Sesostris' brother set his house on fire. His wife told him to lay two of their six children across the flames as a bridge (2.107).", "section": "sec-nz6w2rzr"}, {"id": "z7p3otst", "term": "Sesostris' canals", "definition": "Dug by captives; they brought water inland but ended the use of horses and chariots in Egypt (2.108).", "section": "sec-nz6w2rzr"}, {"id": "i8hby3rw", "term": "Origin of geometry", "definition": "Sesostris gave everyone an equal square plot and taxed it; land lost to the river was measured. Herodotus thinks geometry began here and passed to Greece; the sundial came from Babylon (2.109).", "section": "sec-nz6w2rzr"}, {"id": "1lie3chd", "term": "Darius and Sesostris' statues", "definition": "The priest of Hephaistos refused to let Darius set a statue in front of Sesostris', since Darius never conquered Scythia; Darius agreed (2.110).", "section": "sec-nz6w2rzr"}, {"id": "mw2rbtb0", "term": "Pheros", "definition": "Sesostris' son. He hurled a spear into the flooding Nile and went blind for ten years; cured by a faithful wife's urine, he burned the other women in the city called Red Soil (2.111).", "section": "sec-zi032pmo"}, {"id": "20t2h2tk", "term": "Proteus", "definition": "King from Memphis whose precinct holds the sanctuary of 'Foreign Aphrodite', which Herodotus takes to be Helen's (2.112).", "section": "sec-zi032pmo"}, {"id": "xkidxiu5", "term": "Camp of the Tyrians", "definition": "The area around Proteus' precinct at Memphis, where Phoenicians from Tyre live (2.112).", "section": "sec-zi032pmo"}, {"id": "6kz2nf7a", "term": "Thonis", "definition": "Guard of the Canobic mouth of the Nile who reported Alexandros to Proteus (2.113–2.114).", "section": "sec-zi032pmo"}, {"id": "gfruyknk", "term": "Sanctuary of Herakles (asylum)", "definition": "On the coast at the Canobic mouth; a servant who flees there and is branded can't be touched. Alexandros' servants fled there and denounced him (2.113).", "section": "sec-zi032pmo"}, {"id": "p0syte5e", "term": "Proteus' verdict", "definition": "He won't kill a stranger, but keeps Helen and the stolen property for Menelaos and orders Alexandros to leave within three days (2.115).", "section": "sec-zi032pmo"}, {"id": "wdxskjqp", "term": "Alexandros", "definition": "Paris: the Trojan who abducted Helen from Sparta and was blown to Egypt (2.113).", "section": "sec-zi032pmo"}, {"id": "ynxuio53", "term": "Homer knew the Egypt version", "definition": "He chose the version better suited to epic, but the Iliad (Sidonian robes) and Odyssey show he knew of the wandering to Egypt (2.116).", "section": "sec-zi032pmo"}, {"id": "mgf36idu", "term": "The Cypria", "definition": "Not by Homer, Herodotus argues: in it Alexandros reaches Troy from Sparta in three days with fair winds, unlike the Iliad (2.117).", "section": "sec-zi032pmo"}, {"id": "xq6p6u0o", "term": "Menelaos in Egypt", "definition": "Got Helen back unharmed, then, stuck by bad weather, sacrificed two local children and fled to Libya (2.119).", "section": "sec-zi032pmo"}, {"id": "4i1xqkls", "term": "Herodotus' moral of Troy", "definition": "The Trojans truly didn't have Helen; the gods arranged their ruin to show that great injustices bring great retribution (2.120).", "section": "sec-zi032pmo"}, {"id": "yav8zkyj", "term": "Rhampsinitos", "definition": "Richest king in silver; set up statues called 'Summer' (honored) and 'Winter' (treated the opposite way) at the west gateway (2.121).", "section": "sec-sk9gs0we"}, {"id": "c6y41ppj", "term": "The removable stone", "definition": "The builder of Rhampsinitos' treasury left one stone loose and told his two sons before he died (2.121).", "section": "sec-sk9gs0we"}, {"id": "j6rl88ag", "term": "The master thief", "definition": "Cut off his trapped brother's head, got the guards drunk with leaking wineskins, shaved their right cheeks, and fooled the princess with a corpse's arm. The king pardoned him and gave him his daughter (2.121).", "section": "sec-sk9gs0we"}, {"id": "d9anula7", "term": "Dice with Demeter", "definition": "Rhampsinitos went down to the underworld alive, played dice with Demeter and came back with a golden handkerchief; a festival marks it (2.122).", "section": "sec-sk9gs0we"}, {"id": "yy4kt8eh", "term": "Festival of Demeter", "definition": "A blindfolded priest carrying a new robe is said to be led by two wolves to Demeter's sanctuary and back (2.122).", "section": "sec-sk9gs0we"}], "questions": [{"id": "sb0gjlfr", "prompt": "What changes in Herodotus' method at 2.99?", "choices": ["He stops reporting his own observation and reports what the Egyptians told him", "He switches to Persian sources", "He starts quoting Homer", "He begins listing distances"], "answer": 0, "explanation": "Before 2.99 it was his own observation, judgment and research; now he reports the Egyptians' words, sometimes adding his own observations.", "difficulty": "easy", "section": "sec-nz6w2rzr"}, {"id": "wd3ipl8b", "prompt": "How did Min make room for Memphis?", "choices": ["He drained Lake Moeris", "He dammed the Nile south of the site and moved it into a new channel", "He built on an island", "He cut down a forest"], "answer": 1, "explanation": "The Persians still reinforce that bend each year so it won't flood Memphis (2.99).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "8xxzr0cw", "prompt": "Of the 330 kings after Min, how many were Ethiopians?", "choices": ["Eighteen", "None", "One", "Thirty"], "answer": 0, "explanation": "All were Egyptian men except 18 Ethiopians and one native woman, Nitokris (2.100).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "jb22bosn", "prompt": "How did Nitokris take revenge for her brother?", "choices": ["She flooded an underground banquet hall through a secret conduit", "She exiled them to Ethiopia", "She burned their houses", "She poisoned the guilty at a feast"], "answer": 0, "explanation": "Afterward she threw herself into a chamber full of ashes to escape revenge (2.100).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "3s5f3zhc", "prompt": "What did Sesostris add to pillars in lands that surrendered without a fight?", "choices": ["Nothing at all", "A broken spear", "An image of female genitals", "A chained captive"], "answer": 2, "explanation": "It publicized their cowardice; brave peoples got only his name, land and victory (2.102).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "jxbaqaz6", "prompt": "How far into Europe did Sesostris go, in Herodotus' view?", "choices": ["Scythia and Thrace", "He never crossed into Europe", "Greece", "Italy"], "answer": 0, "explanation": "No pillars appear beyond the Scythians and Thracians (2.103).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "2robkb7p", "prompt": "Which people does Herodotus argue are descendants of Sesostris' army?", "choices": ["The Colchians", "The Ionians", "The Scythians", "The Phoenicians"], "answer": 0, "explanation": "Soldiers stayed near the River Phasis; he says the Colchians remember the Egyptians more than vice versa (2.103–2.104).", "difficulty": "easy", "section": "sec-nz6w2rzr"}, {"id": "jp93fy7j", "prompt": "In 2.104, which evidence does Herodotus say proves nothing on its own?", "choices": ["Their linen", "Their language", "Being black-skinned and woolly-haired, since others look like this too", "Circumcision"], "answer": 2, "explanation": "He leans further on circumcision, practiced from the earliest times only by Colchians, Egyptians and Ethiopians (2.104).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "2vup2i45", "prompt": "Which peoples say they learned circumcision from the Egyptians?", "choices": ["The Persians and Medes", "The Ionians and Lydians", "The Phoenicians and the Syrians of Palestine", "The Scythians and Thracians"], "answer": 2, "explanation": "Syrians near the Thermodon and Parthenios say they learned it recently from the Colchians (2.104).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "hgqw1yn8", "prompt": "What do the Greeks call linen from Colchis?", "choices": ["Phasian", "Egyptian", "Sardonian", "Byssus"], "answer": 2, "explanation": "Only Colchians and Egyptians make linen the same way (2.105).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "jcxnlamt", "prompt": "Who do some people wrongly think the Ionian rock reliefs show?", "choices": ["Darius", "Cyrus", "Memnon", "Croesus"], "answer": 2, "explanation": "Herodotus says records show they are the work of Sesostris (2.106).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "2yrspdwx", "prompt": "How did Sesostris escape his brother's fire at Daphnai?", "choices": ["Rain put it out", "He dug a tunnel", "His soldiers broke down the walls", "His wife had two of their six children laid across the fire as a bridge"], "answer": 3, "explanation": "Two children died; the rest escaped with him (2.107).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "6juz2esl", "prompt": "What unexpected result came from Sesostris' canals?", "choices": ["Lake Moeris dried up", "Egypt could no longer use horses and chariots", "The Nile stopped flooding", "The Delta shrank"], "answer": 1, "explanation": "The canals cut up the land everywhere (2.108).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "9ms5em8a", "prompt": "Where does Herodotus think the Greeks got geometry and the sundial?", "choices": ["Both from Babylon", "Geometry from Phoenicia, the sundial from Egypt", "Geometry from Egypt, the sundial and twelve divisions of the day from Babylon", "Both from Egypt"], "answer": 2, "explanation": "Geometry grew from measuring land the river took from taxed plots (2.109).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "6c1wjsfc", "prompt": "Why did the priest of Hephaistos refuse to let Darius put up a statue?", "choices": ["Darius had burned a temple", "Darius had not conquered the Scythians as Sesostris had", "Darius was a foreigner", "The space was sacred to Ptah"], "answer": 1, "explanation": "Darius, they say, agreed (2.110).", "difficulty": "medium", "section": "sec-nz6w2rzr"}, {"id": "jawf8dot", "prompt": "How was Pheros blinded?", "choices": ["Thieves attacked him", "An oracle cursed his father", "He looked at the sun", "He threw a spear into the flooding Nile"], "answer": 3, "explanation": "His reckless act brought ten years of blindness until the oracle at Bouto gave the cure (2.111).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "9q5yio4h", "prompt": "What did Pheros do after he was cured?", "choices": ["Abdicated", "Built a pyramid", "Freed all the women", "Burned the women in Red Soil, except the one who cured him, whom he married"], "answer": 3, "explanation": "He also gave two huge stone obelisks to the sanctuary of Helios (2.111).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "v0zaeqtr", "prompt": "Why does Herodotus think the 'Foreign Aphrodite' sanctuary at Memphis is really Helen's?", "choices": ["Helen stayed with Proteus, and no other Aphrodite is called 'Foreign'", "Homer says so", "The priests said so", "It has her name carved on it"], "answer": 0, "explanation": "It sits in Proteus' precinct in the Camp of the Tyrians (2.112).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "4aca7od1", "prompt": "Who turned Alexandros in to the Egyptians?", "choices": ["Phoenician sailors", "Menelaos", "His own servants, who fled to the sanctuary of Herakles", "Helen"], "answer": 2, "explanation": "They took asylum and told the priests and the guard Thonis everything (2.113).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "yjx801ut", "prompt": "What was Proteus' decision about Alexandros?", "choices": ["Execute him", "Send him to Troy with Helen", "Let him live but keep Helen and the property for Menelaos, and make him leave in three days", "Enslave him"], "answer": 2, "explanation": "Proteus won't kill strangers driven to Egypt by the winds (2.115).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "zqb0svd2", "prompt": "What does Herodotus conclude about the poem called the Cypria?", "choices": ["It agrees with the Egyptian version", "It wasn't by Homer, because it has Alexandros reach Troy in three days with fair winds", "It is older than the Iliad", "Homer wrote it"], "answer": 1, "explanation": "In the Iliad Alexandros is driven off course, reaching Sidon (2.116–2.117).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "s6e4t9b5", "prompt": "According to the priests, why did the Greeks keep besieging Troy?", "choices": ["They wanted its gold", "An oracle ordered them to", "Menelaos refused peace", "They thought the Trojans were mocking them by saying Helen was in Egypt"], "answer": 3, "explanation": "After taking Troy and not finding Helen, they sent Menelaos to Proteus (2.118).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "kvhxi75n", "prompt": "What did Menelaos do in Egypt that made the Egyptians hate him?", "choices": ["Burned a temple", "Kidnapped a priestess", "Stole Proteus' treasure", "Sacrificed two local children for fair winds"], "answer": 3, "explanation": "He then fled to Libya, hunted (2.119).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "0airu747", "prompt": "What is Herodotus' own lesson from the Trojan War?", "choices": ["Never trust Egyptians", "Great injustices bring great retribution from the gods", "Love conquers all", "Fate cannot be avoided"], "answer": 1, "explanation": "He argues Priam would surely have given Helen back if she were in Troy (2.120).", "difficulty": "medium", "section": "sec-zi032pmo"}, {"id": "hyvxf9iy", "prompt": "What are Rhampsinitos' two statues called?", "choices": ["Day and Night", "Summer and Winter", "Upper and Lower Egypt", "Isis and Osiris"], "answer": 1, "explanation": "'Summer' is honored; 'Winter' is treated the opposite way (2.121).", "difficulty": "easy", "section": "sec-sk9gs0we"}, {"id": "6v2nqvw5", "prompt": "How did the thieves get into Rhampsinitos' treasury?", "choices": ["Through a removable stone their father built in", "Through the roof", "By bribing the guards", "With a copied key"], "answer": 0, "explanation": "The seals stayed intact, which baffled the king (2.121).", "difficulty": "medium", "section": "sec-sk9gs0we"}, {"id": "z28lksk6", "prompt": "Why did the surviving thief cut off his brother's head?", "choices": ["To show the king", "So the body couldn't be identified and ruin them both", "Out of anger", "An oracle demanded it"], "answer": 1, "explanation": "His trapped brother asked him to (2.121).", "difficulty": "medium", "section": "sec-sk9gs0we"}, {"id": "nr8xo9u2", "prompt": "How did the thief get his brother's body back from the guards?", "choices": ["Disguised himself as a priest", "Bribed them with silver", "Spilled wineskins, got them drunk, and shaved their right cheeks", "Dug a tunnel"], "answer": 2, "explanation": "His mother had threatened to turn him in if he didn't (2.121).", "difficulty": "medium", "section": "sec-sk9gs0we"}, {"id": "mxq8mcq7", "prompt": "How did the thief escape the king's daughter?", "choices": ["He wore a disguise", "He climbed out a window", "He bribed her", "He gave her a dead man's arm to hold in the dark"], "answer": 3, "explanation": "The king then pardoned him and gave him his daughter as wife (2.121).", "difficulty": "medium", "section": "sec-sk9gs0we"}, {"id": "r7mvhwpm", "prompt": "What did Rhampsinitos bring back from playing dice with Demeter?", "choices": ["A golden handkerchief", "A wolf", "The key to his treasury", "A silver cup"], "answer": 0, "explanation": "A festival marks his return (2.122).", "difficulty": "medium", "section": "sec-sk9gs0we"}, {"id": "ca1qsqbg", "prompt": "In the festival of Demeter, who leads the blindfolded priest to the sanctuary?", "choices": ["A sacred bull", "Two priestesses", "Two wolves", "The king"], "answer": 2, "explanation": "Herodotus adds that he records what he's told, for anyone who finds it credible (2.122–2.123).", "difficulty": "medium", "section": "sec-sk9gs0we"}], "entries": []}$j$::jsonb, $j${"modes": ["learn", "flashcards", "quiz", "match", "rush"], "questionCount": 10, "rushSeconds": 60, "matchPairs": 6, "shuffle": true, "showExplanations": true, "requireFlashcardsFirst": false, "v": 2}$j$::jsonb, true);
  insert into chapters (course_id, professor_id, number, title, instructions, content, settings, published)
  values (cid, null, 3, 'Samuels: Herodotus and the Black Body', '', $j${"summary": "Tristan Samuels (2015) uses critical race theory to argue that Blackness mattered in Herodotus' ethnography: commentators on 2.104 dismissed Egyptian Blackness to protect their own views, the Greek norm was the tanned Greek man (not Whiteness), and passages like 2.57, 2.104 and 3.101 show Egyptian Blackness and anti-Black prejudice.", "sections": [{"id": "sec-gcxztjot", "title": "The argument and 2.104", "blurb": "Thesis, key Greek words, the new translation"}, {"id": "sec-s6hvfeu2", "title": "Commentators on 2.104", "blurb": "How & Wells, Armayor, Castillos, Lloyd, Dover, Thomas"}, {"id": "sec-zfc5v6l3", "title": "Race in Greco-Roman studies", "blurb": "Snowden, Thompson, Isaac, McCoskey"}, {"id": "sec-bhidewpy", "title": "CRT and the Greek somatic norm", "blurb": "Fields, the tanned Greek man, Physiognomica, vases"}, {"id": "sec-fsax8z9q", "title": "Herodotus and Blacks; conclusion", "blurb": "2.22, 3.101, 2.57, what it means"}], "terms": [{"id": "illgv02w", "term": "Samuels' thesis", "definition": "Contrary to the consensus in Greco-Roman studies, Blackness was a factor in Greek racial thought, and a significant part of Herodotus' ethnography for particular groups.", "section": "sec-gcxztjot"}, {"id": "yzj69tsq", "term": "melagchroes", "definition": "Herodotus' word for the Egyptians/Colchians in 2.104. Usually 'black-' or 'dark-skinned'; Samuels translates it 'black in complexion' and drops 'dark-skinned'.", "section": "sec-gcxztjot"}, {"id": "8bs87att", "term": "oulotriches", "definition": "Herodotus' hair word in 2.104, usually 'woolly-haired'. Samuels prefers 'kinky hair' or 'afro-hair', since 'woolly' comes from 18th-century racist ethnography.", "section": "sec-gcxztjot"}, {"id": "rtnt09dd", "term": "'so more conclusively'", "definition": "Samuels' rendering of the phrase usually read 'but more importantly' in 2.104: circumcision solidifies, rather than outranks, the physical evidence.", "section": "sec-gcxztjot"}, {"id": "pm8roj7m", "term": "The five sections", "definition": "I commentaries on 2.104; II race studies in Greco-Roman scholarship; III race in Classical Greece via CRT; IV Herodotus and Blacks; V implications.", "section": "sec-gcxztjot"}, {"id": "3aagzpnq", "term": "How and Wells", "definition": "Early commentators who called 2.104 'the usual Greek idea' but an exaggeration of 'brown' Egyptians, blaming 'negro slaves' in Memphis. Samuels' example of overt anti-Black racism.", "section": "sec-s6hvfeu2"}, {"id": "wrigqbq6", "term": "Armayor (1978)", "definition": "Used 2.104 to argue Herodotus never went to Egypt, treating his Black Egyptians as a literary tradition (Aeschylus, Pindar).", "section": "sec-s6hvfeu2"}, {"id": "wgmbf152", "term": "Castillos (1984)", "definition": "Egyptologist who disputed Diop; claimed Herodotus' passages meant Ethiopians (a straw man, says Samuels) and assumed a 'white European' norm.", "section": "sec-s6hvfeu2"}, {"id": "k3sqae5p", "term": "Cheikh Anta Diop", "definition": "Scholar who asserted ancient Egypt's Blackness, citing Herodotus 2.57 and 2.104.", "section": "sec-s6hvfeu2"}, {"id": "9k1lghdi", "term": "Alan B. Lloyd", "definition": "Egyptologist whose commentaries render melagchroes as 'bronzed to black' or 'swarthy'. Samuels calls his logic circular: Egyptians looked Black but weren't.", "section": "sec-s6hvfeu2"}, {"id": "9ekazxx8", "term": "Kenneth Dover (1998)", "definition": "Read melagchroes as 'dark-skinned', the deep tan of some Athenians, and called the Colchian description a mistaken tradition.", "section": "sec-s6hvfeu2"}, {"id": "m2eajwom", "term": "Rosalind Thomas", "definition": "Accepts Herodotus saw Egyptians as Black but later says he argued mainly from custom and language; Samuels says she overlooks Blackness.", "section": "sec-s6hvfeu2"}, {"id": "depmdx94", "term": "Frank Snowden", "definition": "First systematic study of Black people in antiquity (Blacks in Antiquity; Before Color Prejudice): argued the ancient world wasn't anti-Black and equated Blackness with Aithiopians.", "section": "sec-zfc5v6l3"}, {"id": "vmskqe8c", "term": "Lloyd Thompson (1989)", "definition": "Romans and Blacks: found the Roman somatic norm was 'pale-brown', so Whiteness meant nothing to Roman identity.", "section": "sec-zfc5v6l3"}, {"id": "82ojnr6v", "term": "Benjamin Isaac (2004)", "definition": "The Invention of Racism in Classical Antiquity: excluded Ethiopians, saying Blacks were a rare, expensive type of slave, and claimed Egyptian physical traits didn't interest Herodotus.", "section": "sec-zfc5v6l3"}, {"id": "ihpcwrjc", "term": "Denise McCoskey (2012)", "definition": "Race: Antiquity and Its Legacy: uses racial formation and CRT, but calls Egyptian Blackness in Herodotus 'minor', 'merely passing'; Samuels calls this White fragility.", "section": "sec-zfc5v6l3"}, {"id": "l5vfdqzn", "term": "Racial formation", "definition": "The idea (Omi and Winant; used by McCoskey) that race is a social construct shaped by social and historical forces.", "section": "sec-zfc5v6l3"}, {"id": "ls6gpu23", "term": "Frank Martin (1984)", "definition": "Quoted: it's impossible to use facts to convince most Westerners taught to equate 'Negro' with inferiority that ancient Egyptians were Black.", "section": "sec-zfc5v6l3"}, {"id": "k7p2fdxr", "term": "Critical race theory (CRT)", "definition": "Movement begun in the US in the 1970s that addresses the permanence of racism, informed by the radical thought of people of color.", "section": "sec-bhidewpy"}, {"id": "5z79a4o0", "term": "Barbara Fields: race vs. racism", "definition": "Race is a symmetrical mode of identification; racism is assigning people to an inferior category: asymmetrical, an imposition.", "section": "sec-bhidewpy"}, {"id": "mbdyrznz", "term": "Tanned Greek Man", "definition": "The Greek somatic norm. Blackness was seen in relation to the tanned Greek man, not to Whiteness.", "section": "sec-bhidewpy"}, {"id": "vynmcbbs", "term": "Whiteness in Greek thought", "definition": "Per James Dee, a trait of Greek women or of barbarians north of the Alps, not of the Greek norm.", "section": "sec-bhidewpy"}, {"id": "jvh3ydt1", "term": "Odysseus melagchroes", "definition": "Homer (Od. 16.175) calls Odysseus melagchroes; Samuels reads it 'tanned' for Greek men, not 'sunburnt' or 'dark'.", "section": "sec-bhidewpy"}, {"id": "hk8dl4yt", "term": "Aeschylus' 'sun-blackened race'", "definition": "His description of the Egyptians (Suppliants 154–155), linking Blackness to the sun.", "section": "sec-bhidewpy"}, {"id": "rprmw2fn", "term": "Aristotelian Physiognomica", "definition": "Those too black are cowards (Egyptians, Aithiopians); those too white are cowards (women); the middle color favors bravery.", "section": "sec-bhidewpy"}, {"id": "rsbl8n24", "term": "Janiform vases", "definition": "Athenian two-faced vases pairing Greek women's faces with Black faces: both central 'others' to the tanned Greek man.", "section": "sec-bhidewpy"}, {"id": "kvxn3ge3", "term": "Prejudice vs. racism (Herodotus)", "definition": "Herodotus had racial prejudices, but as a visitor, not a colonial ruler, they had no systematic effect on the peoples he described.", "section": "sec-bhidewpy"}, {"id": "ut0ifpbl", "term": "Herodotus 2.22", "definition": "Explains Aithiopian blackness (melanes) by the sun's heat: Greek climatic theory of racial difference.", "section": "sec-fsax8z9q"}, {"id": "9xtb84er", "term": "Herodotus 3.101", "definition": "Says Indians mate in public like cattle, are black like Aithiopians, and have black semen; Samuels' main example of gendered, sexualized anti-Black racism.", "section": "sec-fsax8z9q"}, {"id": "jmetwm7p", "term": "Herodotus 2.57", "definition": "The 'black dove' of Dodona is an Egyptian woman: the only explicit mention in the Histories of Egyptian women's Blackness.", "section": "sec-fsax8z9q"}, {"id": "wu9oa0im", "term": "Conclusion: timing of anti-Blackness", "definition": "Anti-Blackness predates the transatlantic slave trade and capitalism; Blackness preceded Whiteness. Snowden's 'before color prejudice' thesis is dismissible.", "section": "sec-fsax8z9q"}, {"id": "idbveryu", "term": "'Black races'", "definition": "Samuels' claim that there were several Black racial groups (e.g., Egyptians, Aithiopians), not one ethnically diverse Black race, in Greek thought.", "section": "sec-fsax8z9q"}], "questions": [{"id": "0l3cv65o", "prompt": "What method does Samuels use to analyze Herodotus' view of Blackness?", "choices": ["Critical race theory", "Archaeological survey", "Linguistic statistics", "Comparative mythology"], "answer": 0, "explanation": "The subtitle is 'A Critical Race Theory Analysis'.", "difficulty": "easy", "section": "sec-gcxztjot"}, {"id": "zrxvzb20", "prompt": "What is Samuels' main claim?", "choices": ["Greeks had no idea of race", "Blackness was a factor in Greek racial thought and significant in Herodotus' ethnography", "Herodotus never visited Egypt", "Egyptians were not described physically by Herodotus"], "answer": 1, "explanation": "This runs against the consensus in Greco-Roman studies.", "difficulty": "medium", "section": "sec-gcxztjot"}, {"id": "2a1vly7r", "prompt": "Why does Samuels say Herodotus' view of Blackness is usually only discussed through 2.104?", "choices": ["Because Herodotus said it was important", "It's the only passage on Egypt", "Because of the modern debate over ancient Egyptian racial identity", "Because 2.104 was recently found"], "answer": 2, "explanation": "Commentators focused on defending their views about whether the Egyptians were Black.", "difficulty": "medium", "section": "sec-gcxztjot"}, {"id": "gh5yh2ut", "prompt": "How does Samuels translate oulotriches for Black groups?", "choices": ["Curly-haired", "Kinky hair or afro-hair", "Long-haired", "Woolly-haired"], "answer": 1, "explanation": "'Woolly' comes from 18th-century European ethnography that treated Black hair as animal-like.", "difficulty": "medium", "section": "sec-gcxztjot"}, {"id": "6hh8dlua", "prompt": "In Samuels' translation of 2.104, what does the phrase usually read as 'but more importantly' become?", "choices": ["'so more conclusively'", "'and therefore'", "'as everyone knows'", "'but less certainly'"], "answer": 0, "explanation": "Circumcision is solidifying evidence, so Herodotus used both physical appearance and customs.", "difficulty": "medium", "section": "sec-gcxztjot"}, {"id": "cymummfr", "prompt": "Why, per Samuels, did Herodotus add circumcision as evidence in 2.104?", "choices": ["Other Black groups looked similar, so he needed further evidence", "He doubted the Colchians were black", "Physical traits didn't matter to him", "His sources insisted"], "answer": 0, "explanation": "There were multiple Black groups in the Greek world, so appearance alone couldn't single out Egyptians.", "difficulty": "medium", "section": "sec-gcxztjot"}, {"id": "jgpcdlmt", "prompt": "How did How and Wells explain Herodotus' description of Egyptians?", "choices": ["He was quoting Homer", "He never went to Egypt", "He meant Ethiopians", "He was confused by 'negro slaves' he saw in Memphis"], "answer": 3, "explanation": "Samuels calls this an anti-Black stereotype and an example of overt racism in early commentaries.", "difficulty": "medium", "section": "sec-s6hvfeu2"}, {"id": "jks36swz", "prompt": "What did Armayor use 2.104 to argue?", "choices": ["Colchians were Scythians", "Herodotus never went to Egypt", "Egyptians were Greek", "Herodotus was a racist"], "answer": 1, "explanation": "He treated Black Egyptians as a literary tradition; Samuels says he gives no motive for such a tradition.", "difficulty": "medium", "section": "sec-s6hvfeu2"}, {"id": "a3d7vdl6", "prompt": "Why does Samuels call Castillos' criticism of Diop a straw man?", "choices": ["Diop never cited Herodotus", "Castillos agreed with Diop", "Diop was not an Egyptologist", "Diop cited 2.57 and 2.104, which clearly refer to Egyptians, not Ethiopians"], "answer": 3, "explanation": "Castillos assumed Aithiopians were the only Blacks in Greek eyes.", "difficulty": "medium", "section": "sec-s6hvfeu2"}, {"id": "qq92kpno", "prompt": "What does Samuels call Lloyd's reasoning about Egyptian appearance?", "choices": ["Sound but incomplete", "Circular: Egyptians looked like Black people but weren't Black", "Based on new evidence", "Too accepting of Herodotus"], "answer": 1, "explanation": "Lloyd concedes the features would 'certainly' be found among Egyptians yet denies they were Black.", "difficulty": "medium", "section": "sec-s6hvfeu2"}, {"id": "hbiyuyol", "prompt": "Which passage does Samuels say Lloyd ignored that shows Herodotus' interest in Egyptian appearance?", "choices": ["7.70", "3.38", "2.57", "1.1"], "answer": 2, "explanation": "Lloyd said Herodotus discussed Egyptian physical traits only at 2.104.", "difficulty": "medium", "section": "sec-s6hvfeu2"}, {"id": "y0ro3ba0", "prompt": "How did Dover read melagchroes for the Colchians?", "choices": ["As a poetic metaphor", "As bronze-colored armor", "As 'dark-skinned', the deep tan of some Athenians", "As black-skinned"], "answer": 2, "explanation": "Samuels says this assumes Athenian identity was White.", "difficulty": "medium", "section": "sec-s6hvfeu2"}, {"id": "q6cdv5i5", "prompt": "What does Samuels criticize in Rosalind Thomas' reading?", "choices": ["She denies Herodotus visited Egypt", "She says the Colchian argument rests mainly on custom and language, overlooking Blackness", "She calls Herodotus a liar", "She mistranslates circumcision"], "answer": 1, "explanation": "Herodotus says the physical similarities started his conjecture.", "difficulty": "medium", "section": "sec-s6hvfeu2"}, {"id": "jjwxrv7y", "prompt": "What was Frank Snowden's main contention?", "choices": ["The Greco-Roman world wasn't anti-Black like the modern world", "Herodotus was unreliable", "Romans invented racism", "Egyptians were Black"], "answer": 0, "explanation": "Samuels says Greek texts show clear anti-Black prejudice, and Snowden wrongly made Blackness exclusive to Aithiopians.", "difficulty": "medium", "section": "sec-zfc5v6l3"}, {"id": "xb85gflr", "prompt": "What did Lloyd Thompson identify as the Roman somatic norm?", "choices": ["Pale-brown", "Tanned", "White", "Olive"], "answer": 0, "explanation": "So Whiteness had no socio-cultural significance for Roman identity.", "difficulty": "medium", "section": "sec-zfc5v6l3"}, {"id": "p0bqarwh", "prompt": "Why does Benjamin Isaac leave Ethiopians out of his study?", "choices": ["He says they were a rare slave type, partly mythical, with little impact", "The sources are lost", "They didn't exist", "He covers them in another book"], "answer": 0, "explanation": "Samuels calls tying the Black presence in Athens only to servitude a stereotype.", "difficulty": "medium", "section": "sec-zfc5v6l3"}, {"id": "lr350kck", "prompt": "How does McCoskey describe Herodotus' references to Egyptian Blackness?", "choices": ["Mistranslated", "Fabricated", "'Minor' and 'merely passing'", "Central"], "answer": 2, "explanation": "She also calls Afrocentric claims a 'dangerous racial essentialism'; Samuels calls her argument a reflex of White fragility.", "difficulty": "medium", "section": "sec-zfc5v6l3"}, {"id": "gypf8spd", "prompt": "What does Samuels credit McCoskey for?", "choices": ["Translating Herodotus", "Discovering the Janiform vases", "Using racial formation and CRT as a framework for race in antiquity", "Proving Egyptians were Black"], "answer": 2, "explanation": "But she doesn't contextualize Blackness within Greek or Roman racial formation.", "difficulty": "medium", "section": "sec-zfc5v6l3"}, {"id": "d4v4xzh6", "prompt": "Per Barbara Fields, how does racism differ from race?", "choices": ["Racism is symmetrical, race is not", "Race is biological, racism cultural", "They are the same", "Race is a symmetrical identification; racism assigns people to an inferior category, an asymmetrical imposition"], "answer": 3, "explanation": "Targets of racism can only challenge or navigate its obstacles.", "difficulty": "medium", "section": "sec-bhidewpy"}, {"id": "ydwv6ovs", "prompt": "What was the Greek somatic norm, according to Samuels?", "choices": ["The tanned Greek man", "Bronze", "White", "Pale-brown"], "answer": 0, "explanation": "Blackness was seen in relation to the tanned Greek man, not Whiteness.", "difficulty": "easy", "section": "sec-bhidewpy"}, {"id": "bufx8yt0", "prompt": "According to James Dee, whom did Greeks associate with Whiteness?", "choices": ["Persians", "Greek men", "Egyptians", "Greek women or barbarians north of the Alps"], "answer": 3, "explanation": "So the Greek norm can't have been White.", "difficulty": "medium", "section": "sec-bhidewpy"}, {"id": "mmt399j2", "prompt": "How should melagchroes be translated when Homer uses it for Odysseus?", "choices": ["Sunburnt", "Dark", "Tanned", "Black"], "answer": 2, "explanation": "'He was tanned in color again'; 'tan' applies only to Greek men.", "difficulty": "medium", "section": "sec-bhidewpy"}, {"id": "msqsr9ik", "prompt": "What does the Aristotelian Physiognomica say about color and bravery?", "choices": ["Too black (Egyptians, Aithiopians) and too white (women) are cowards; the middle color favors bravery", "Color has nothing to do with bravery", "Only white is brave", "Darker people are braver"], "answer": 0, "explanation": "Samuels calls this an indisputable example of anti-Blackness in Greek thought.", "difficulty": "medium", "section": "sec-bhidewpy"}, {"id": "7v7vytul", "prompt": "What do the Janiform vases pair together?", "choices": ["Egyptians and Aithiopians", "Gods and heroes", "Greek men and Persians", "Greek women and Black people"], "answer": 3, "explanation": "Both were central 'others' to the tanned Greek man.", "difficulty": "medium", "section": "sec-bhidewpy"}, {"id": "5130qvlz", "prompt": "Why does Samuels distinguish Herodotus' racial prejudice from racism?", "choices": ["Racism didn't exist yet", "As a visitor, not an imperial or colonial ruler, his prejudice had no systematic effect", "He only wrote about Greeks", "Herodotus had none"], "answer": 1, "explanation": "It may still reflect racism in the Greek city-states where he lived.", "difficulty": "medium", "section": "sec-bhidewpy"}, {"id": "vu15iq7v", "prompt": "How does Herodotus explain Aithiopian blackness in 2.22?", "choices": ["The heat of the sun", "Diet", "A curse", "Ancestry from Egypt"], "answer": 0, "explanation": "This matches Greek climatic theory.", "difficulty": "medium", "section": "sec-fsax8z9q"}, {"id": "bsq4rjdy", "prompt": "Which passage is Samuels' main example of gendered anti-Black racism in Herodotus?", "choices": ["4.42", "3.101", "1.1", "2.35"], "answer": 1, "explanation": "Indians and Aithiopians are said to mate in public like cattle and have black semen.", "difficulty": "medium", "section": "sec-fsax8z9q"}, {"id": "9mxix2ws", "prompt": "What does Samuels say the 'black dove' of 2.57 shows?", "choices": ["Doves were sacred in Egypt", "The story is Phoenician", "Herodotus disliked Egyptians", "Herodotus took an Egyptian Black woman to have founded Dodona's oracle; melas connotes Blackness"], "answer": 3, "explanation": "It's the only explicit mention of Egyptian women's Blackness in the Histories.", "difficulty": "medium", "section": "sec-fsax8z9q"}, {"id": "ix8mju8n", "prompt": "According to Samuels' conclusion, when did Western anti-Blackness begin?", "choices": ["With Rome", "In the 19th century", "With the transatlantic slave trade", "Before it: Herodotus shows anti-Black prejudice in antiquity"], "answer": 3, "explanation": "Blackness preceded Whiteness, and Snowden's 'before color prejudice' thesis is dismissible.", "difficulty": "medium", "section": "sec-fsax8z9q"}, {"id": "9z6hy6al", "prompt": "Instead of one ethnically diverse Black race, Samuels says Greek thought had…", "choices": ["no idea of Blackness", "only Aithiopian Blacks", "a White/Black binary", "several Black races, such as Egyptians and Aithiopians"], "answer": 3, "explanation": "Herodotus' mention of straight-haired Asiatic Aithiopians shows there was no 'True Black' type.", "difficulty": "medium", "section": "sec-fsax8z9q"}], "entries": []}$j$::jsonb, $j${"modes": ["learn", "flashcards", "quiz", "match", "rush"], "questionCount": 10, "rushSeconds": 60, "matchPairs": 6, "shuffle": true, "showExplanations": true, "requireFlashcardsFirst": false, "v": 2}$j$::jsonb, true);
  insert into chapters (course_id, professor_id, number, title, instructions, content, settings, published)
  values (cid, null, 4, 'All Mon 11/2 readings: Herodotus 2 + Samuels', '', $j${"summary": "Every question from Herodotus 2.1–2.64, 2.99–2.122 and Samuels in one set. Pick a reading as a topic, or play them all.", "sections": [{"id": "sec-jf8k2xgq", "title": "Herodotus 2.1–2.64", "blurb": "Land, Nile, customs, gods"}, {"id": "sec-my15bzm2", "title": "Herodotus 2.99–2.122", "blurb": "Kings from Min to Rhampsinitos"}, {"id": "sec-vlq0g9o2", "title": "Samuels (2015)", "blurb": "Herodotus and the Black Body"}], "terms": [{"id": "q6ej9gex", "term": "Psammetichos (experiment)", "definition": "Egyptian king who had two newborns raised by a shepherd with no one speaking near them, to learn which people was oldest (2.2).", "section": "sec-jf8k2xgq"}, {"id": "b3zx24pk", "term": "bekos", "definition": "The children's first word. It means 'bread' in Phrygian, so the Egyptians conceded the Phrygians were older than themselves (2.2).", "section": "sec-jf8k2xgq"}, {"id": "3jsgd9mv", "term": "Priests of Hephaistos at Memphis", "definition": "Herodotus' main source for the bekos story; he also checked their accounts at Thebes and Heliopolis (2.2–2.3).", "section": "sec-jf8k2xgq"}, {"id": "2gyf2tm9", "term": "Egyptian calendar", "definition": "12 months of 30 days plus 5 extra days a year. Herodotus thinks it wiser than the Greek system of an extra month every other year (2.4).", "section": "sec-jf8k2xgq"}, {"id": "mhhyfghm", "term": "Min", "definition": "The first king of Egypt, according to the priests. In his day all Egypt except the district of Thebes was swamp (2.4).", "section": "sec-jf8k2xgq"}, {"id": "c59cc5ru", "term": "'Gift of the river'", "definition": "Herodotus' description of the Egypt Greeks sail to: land deposited by the Nile (2.5).", "section": "sec-jf8k2xgq"}, {"id": "np1vxufl", "term": "schoinos", "definition": "An Egyptian unit of distance ('rope') equal to 60 stades; Herodotus gives the coast as 60 schoinoi, about 397 miles (2.6).", "section": "sec-jf8k2xgq"}, {"id": "3hdwnzfe", "term": "Ionian view of Egypt", "definition": "That Egypt is only the Delta and the world has three parts. Herodotus says the Delta would then be a fourth part, and calls the view absurd (2.15–2.16).", "section": "sec-jf8k2xgq"}, {"id": "0zugx570", "term": "Oracle of Ammon (on who is Egyptian)", "definition": "Told the people of Mareia and Apis, who wanted to eat cow meat, that Egypt is all land the Nile floods and Egyptians are those below Elephantine who drink its water (2.18).", "section": "sec-jf8k2xgq"}, {"id": "4bsz6pdo", "term": "Etesian winds theory", "definition": "Greek idea that the summer north winds hold the Nile back and cause the flood. Refuted: the Nile floods even when they don't blow (2.20).", "section": "sec-jf8k2xgq"}, {"id": "pad9f3zi", "term": "Ocean theory", "definition": "Greek idea that the Nile flows from Ocean, which surrounds the world. Herodotus says it can't be refuted because it's in the unknown, and Ocean was likely invented by Homer or earlier poets (2.21, 2.23).", "section": "sec-jf8k2xgq"}, {"id": "i0k72bm6", "term": "Melting snow theory", "definition": "The 'most plausible' but 'most erroneous' theory, per Herodotus: the Nile flows from the hottest lands, where winds are warm and people are black from the sun (2.22).", "section": "sec-jf8k2xgq"}, {"id": "cmpbfyos", "term": "Herodotus' sun theory", "definition": "In winter storms drive the sun south over Libya, where it draws water up from the Nile, so the Nile alone runs low in winter (2.24–2.26).", "section": "sec-jf8k2xgq"}, {"id": "z8w81cr1", "term": "Scribe of Athena's treasury at Sais", "definition": "The only person who claimed to know the Nile's sources: bottomless springs between the mountains Krophi and Mophi. Herodotus thought he was joking (2.28).", "section": "sec-jf8k2xgq"}, {"id": "qo971joa", "term": "Elephantine", "definition": "City at the First Cataract. Herodotus says he saw this far himself; beyond it he relies on hearsay (2.29).", "section": "sec-jf8k2xgq"}, {"id": "hjsz230m", "term": "Meroe", "definition": "The metropolis of the Ethiopians, where only Zeus and Dionysos are worshiped and an oracle of Zeus decides their wars (2.29).", "section": "sec-jf8k2xgq"}, {"id": "34s1da83", "term": "The Deserters (Asmach)", "definition": "240,000 Egyptian soldiers who left King Psammetichos for Ethiopia after three years on garrison duty without relief (2.30).", "section": "sec-jf8k2xgq"}, {"id": "lagds20f", "term": "Nasamonian youths", "definition": "Five young Libyans who crossed the desert westward and were captured by small, black-skinned people living by a river with crocodiles (2.32).", "section": "sec-jf8k2xgq"}, {"id": "6pmnm1dr", "term": "Ister (Danube)", "definition": "Europe's great river. Herodotus argues the Nile's course through Libya equals the Ister's course through Europe (2.33–2.34).", "section": "sec-jf8k2xgq"}, {"id": "5m2wf5v1", "term": "Egyptian 'opposite' customs", "definition": "Women sell in the market while men weave at home; men carry loads on their heads, women on their shoulders (2.35).", "section": "sec-jf8k2xgq"}, {"id": "q3l80fpu", "term": "Egyptian writing", "definition": "Written right to left, with two scripts, called 'sacred' and 'public' (2.36).", "section": "sec-jf8k2xgq"}, {"id": "j9wh3rpb", "term": "Egyptian priests (purity)", "definition": "Shave their whole bodies every other day, wear only linen and papyrus sandals, bathe twice a day and twice a night, and may not eat fish (2.37).", "section": "sec-jf8k2xgq"}, {"id": "2z6btcfy", "term": "Inspection of sacrificial bulls", "definition": "Bulls belong to Epaphos (Apis); one black hair makes a bull unclean. A clean bull is sealed with papyrus and clay; sacrificing an unmarked one means death (2.38).", "section": "sec-jf8k2xgq"}, {"id": "pne2qg0c", "term": "Curses on the bull's head", "definition": "Egyptians curse the head so any evil falls on it, then sell it to Greeks or throw it in the river; no Egyptian eats an animal's head (2.39).", "section": "sec-jf8k2xgq"}, {"id": "rke1d2s6", "term": "Isis and cows", "definition": "Female cattle are sacred to Isis, whose statue has cow's horns like the Greek Io; Egyptians won't kiss a Greek or use his knife because Greeks eat cows (2.41).", "section": "sec-jf8k2xgq"}, {"id": "ravq5un2", "term": "Atarbechis", "definition": "City on the island of Prosopitis that sends barges to collect buried bulls' bones from across Egypt (2.41).", "section": "sec-jf8k2xgq"}, {"id": "lzrfqdsl", "term": "Ram-headed Zeus (Ammon)", "definition": "Zeus showed himself to Herakles wrapped in a ram's fleece, so Thebans don't sacrifice rams and the Ammonians took their name from Ammon (2.42).", "section": "sec-jf8k2xgq"}, {"id": "u6995bqa", "term": "Egyptian Herakles", "definition": "An ancient god, one of the twelve. Herodotus sails to Tyre and Thasos and concludes Herakles is far older than the Greek son of Amphitryon (2.43–2.44).", "section": "sec-jf8k2xgq"}, {"id": "ocnq2p1c", "term": "Mendes", "definition": "Egyptian name for both Pan and the most honored he-goat; the Mendesians don't sacrifice goats (2.46).", "section": "sec-jf8k2xgq"}, {"id": "w68sb2ko", "term": "Swineherds", "definition": "The only native Egyptians barred from every sanctuary; no one marries them, so they marry among themselves (2.47).", "section": "sec-jf8k2xgq"}, {"id": "4a2cw8t8", "term": "Melampous", "definition": "The Greek who taught the Hellenes the name of Dionysos, his sacrifice and the phallic procession, using what he learned from Egypt (2.49).", "section": "sec-jf8k2xgq"}, {"id": "79jqux1x", "term": "Names of the gods", "definition": "Herodotus says almost all came to Hellas from Egypt, except Poseidon (from Libya), the Dioskouroi, Hera, Histia, Themis, the Graces and the Nereids (2.50).", "section": "sec-jf8k2xgq"}, {"id": "7r7fddqq", "term": "Pelasgians", "definition": "Thought to be Greece's original inhabitants. They taught the Athenians to make statues of Hermes with an erect phallus and learned the gods' names from Egypt (2.51–2.52).", "section": "sec-jf8k2xgq"}, {"id": "3ljatek0", "term": "Oracle of Dodona", "definition": "Thought to be the oldest Greek oracle; it told the Pelasgians to use the gods' names that came from the barbarians (2.52).", "section": "sec-jf8k2xgq"}, {"id": "v7gznogv", "term": "Hesiod and Homer", "definition": "Poets who, Herodotus says, lived no more than 400 years before him and gave the Greeks the theogony, the gods' epithets, honors and looks (2.53).", "section": "sec-jf8k2xgq"}, {"id": "wcndf0n5", "term": "Two black doves", "definition": "Dodona's story: doves flew from Egyptian Thebes, one founding the oracle at Dodona and one Ammon's in Libya (2.55).", "section": "sec-jf8k2xgq"}, {"id": "1475s0zz", "term": "Herodotus' reading of the doves", "definition": "The 'dove' was an Egyptian woman sold by Phoenicians; her foreign speech sounded like a bird's, and calling her black shows she was Egyptian (2.56–2.57).", "section": "sec-jf8k2xgq"}, {"id": "xao0ydru", "term": "Boubastis festival", "definition": "Egypt's most popular festival, for Artemis; up to 700,000 people come by barge and drink more wine than all year (2.59–2.60).", "section": "sec-jf8k2xgq"}, {"id": "yqdvyyt6", "term": "Feast of the Burning Lamps", "definition": "Festival at Sais for Athena, when lamps burn all night across Egypt (2.62).", "section": "sec-jf8k2xgq"}, {"id": "r7pkg5uq", "term": "Papremis festival", "definition": "Festival for Ares with a club fight between priests and men fulfilling vows, said to recall Ares forcing his way in to his mother (2.63).", "section": "sec-jf8k2xgq"}, {"id": "y4sv2kqn", "term": "The turn at 2.99", "definition": "Up to here Herodotus relied on his own observation and research; from here he reports what the Egyptians told him, adding his own observations at times.", "section": "sec-my15bzm2"}, {"id": "gybmk27k", "term": "Min (founding Memphis)", "definition": "The first king. He dammed the Nile about 11 miles south of Memphis, moved it into a new channel, founded Memphis on the dried land and built the sanctuary of Hephaistos (2.99).", "section": "sec-my15bzm2"}, {"id": "cwzsrezn", "term": "330 kings", "definition": "The kings the priests read from a papyrus roll after Min: all Egyptian men except 18 Ethiopians and one native woman (2.100).", "section": "sec-my15bzm2"}, {"id": "9wt3r07e", "term": "Nitokris", "definition": "The one queen. She avenged her murdered brother by inviting the guilty to a feast in an underground chamber and flooding it, then threw herself into a room full of ashes (2.100).", "section": "sec-my15bzm2"}, {"id": "z7kzj45d", "term": "Moeris", "definition": "The last of the unremarkable kings: built the north gateway of Hephaistos' sanctuary and dug a lake with pyramids in it (2.101).", "section": "sec-my15bzm2"}, {"id": "6fhnjxy3", "term": "Sesostris", "definition": "Conquering king who sailed from the Arabian Gulf, then marched through Asia into Europe, beating the Scythians and Thracians (2.102–2.103).", "section": "sec-my15bzm2"}, {"id": "l3vvf70x", "term": "Sesostris' pillars", "definition": "Inscribed with his name and country. For peoples who gave up without a fight he added female genitals to mark their cowardice (2.102).", "section": "sec-my15bzm2"}, {"id": "mmhj971i", "term": "Colchians", "definition": "People by the Phasis River whom Herodotus calls Egyptians left behind by Sesostris' army (2.103–2.104).", "section": "sec-my15bzm2"}, {"id": "g0iouqvj", "term": "2.104 evidence", "definition": "Black skin and woolly (kinky) hair, which he says proves nothing alone, and 'more' that only Colchians, Egyptians and Ethiopians have circumcised from the earliest times (2.104).", "section": "sec-my15bzm2"}, {"id": "fbutxwnm", "term": "Linen of Colchis", "definition": "Made by the same method as Egyptian linen; the Greeks call it 'Sardonian' (2.105).", "section": "sec-my15bzm2"}, {"id": "ibc2i9t8", "term": "Rock reliefs in Ionia", "definition": "Two carved figures with spear and bow on the roads Ephesus–Phocaea and Sardis–Smyrna, inscribed 'I acquired this land by the strength of my shoulders'. Some say Memnon; Herodotus says Sesostris (2.106).", "section": "sec-my15bzm2"}, {"id": "rfnqbeb8", "term": "The fire at Daphnai", "definition": "Sesostris' brother set his house on fire. His wife told him to lay two of their six children across the flames as a bridge (2.107).", "section": "sec-my15bzm2"}, {"id": "jsh3n7rt", "term": "Sesostris' canals", "definition": "Dug by captives; they brought water inland but ended the use of horses and chariots in Egypt (2.108).", "section": "sec-my15bzm2"}, {"id": "s8v6bssp", "term": "Origin of geometry", "definition": "Sesostris gave everyone an equal square plot and taxed it; land lost to the river was measured. Herodotus thinks geometry began here and passed to Greece; the sundial came from Babylon (2.109).", "section": "sec-my15bzm2"}, {"id": "v4u2vtkx", "term": "Darius and Sesostris' statues", "definition": "The priest of Hephaistos refused to let Darius set a statue in front of Sesostris', since Darius never conquered Scythia; Darius agreed (2.110).", "section": "sec-my15bzm2"}, {"id": "if7ztm98", "term": "Pheros", "definition": "Sesostris' son. He hurled a spear into the flooding Nile and went blind for ten years; cured by a faithful wife's urine, he burned the other women in the city called Red Soil (2.111).", "section": "sec-my15bzm2"}, {"id": "vq9vodqc", "term": "Proteus", "definition": "King from Memphis whose precinct holds the sanctuary of 'Foreign Aphrodite', which Herodotus takes to be Helen's (2.112).", "section": "sec-my15bzm2"}, {"id": "5sra7c98", "term": "Camp of the Tyrians", "definition": "The area around Proteus' precinct at Memphis, where Phoenicians from Tyre live (2.112).", "section": "sec-my15bzm2"}, {"id": "xbygmijz", "term": "Thonis", "definition": "Guard of the Canobic mouth of the Nile who reported Alexandros to Proteus (2.113–2.114).", "section": "sec-my15bzm2"}, {"id": "lqn96efo", "term": "Sanctuary of Herakles (asylum)", "definition": "On the coast at the Canobic mouth; a servant who flees there and is branded can't be touched. Alexandros' servants fled there and denounced him (2.113).", "section": "sec-my15bzm2"}, {"id": "hst9zxb7", "term": "Proteus' verdict", "definition": "He won't kill a stranger, but keeps Helen and the stolen property for Menelaos and orders Alexandros to leave within three days (2.115).", "section": "sec-my15bzm2"}, {"id": "urrfd2jt", "term": "Alexandros", "definition": "Paris: the Trojan who abducted Helen from Sparta and was blown to Egypt (2.113).", "section": "sec-my15bzm2"}, {"id": "dqeb45ej", "term": "Homer knew the Egypt version", "definition": "He chose the version better suited to epic, but the Iliad (Sidonian robes) and Odyssey show he knew of the wandering to Egypt (2.116).", "section": "sec-my15bzm2"}, {"id": "gpv381ze", "term": "The Cypria", "definition": "Not by Homer, Herodotus argues: in it Alexandros reaches Troy from Sparta in three days with fair winds, unlike the Iliad (2.117).", "section": "sec-my15bzm2"}, {"id": "gmzk4oxd", "term": "Menelaos in Egypt", "definition": "Got Helen back unharmed, then, stuck by bad weather, sacrificed two local children and fled to Libya (2.119).", "section": "sec-my15bzm2"}, {"id": "w5bgqv6w", "term": "Herodotus' moral of Troy", "definition": "The Trojans truly didn't have Helen; the gods arranged their ruin to show that great injustices bring great retribution (2.120).", "section": "sec-my15bzm2"}, {"id": "uhmpsgvh", "term": "Rhampsinitos", "definition": "Richest king in silver; set up statues called 'Summer' (honored) and 'Winter' (treated the opposite way) at the west gateway (2.121).", "section": "sec-my15bzm2"}, {"id": "z6nhpefj", "term": "The removable stone", "definition": "The builder of Rhampsinitos' treasury left one stone loose and told his two sons before he died (2.121).", "section": "sec-my15bzm2"}, {"id": "fnmgx1k9", "term": "The master thief", "definition": "Cut off his trapped brother's head, got the guards drunk with leaking wineskins, shaved their right cheeks, and fooled the princess with a corpse's arm. The king pardoned him and gave him his daughter (2.121).", "section": "sec-my15bzm2"}, {"id": "3j8c2nbr", "term": "Dice with Demeter", "definition": "Rhampsinitos went down to the underworld alive, played dice with Demeter and came back with a golden handkerchief; a festival marks it (2.122).", "section": "sec-my15bzm2"}, {"id": "ujyt38mb", "term": "Festival of Demeter", "definition": "A blindfolded priest carrying a new robe is said to be led by two wolves to Demeter's sanctuary and back (2.122).", "section": "sec-my15bzm2"}, {"id": "6y2vtgkr", "term": "Samuels' thesis", "definition": "Contrary to the consensus in Greco-Roman studies, Blackness was a factor in Greek racial thought, and a significant part of Herodotus' ethnography for particular groups.", "section": "sec-vlq0g9o2"}, {"id": "53otgojc", "term": "melagchroes", "definition": "Herodotus' word for the Egyptians/Colchians in 2.104. Usually 'black-' or 'dark-skinned'; Samuels translates it 'black in complexion' and drops 'dark-skinned'.", "section": "sec-vlq0g9o2"}, {"id": "mcbyva0r", "term": "oulotriches", "definition": "Herodotus' hair word in 2.104, usually 'woolly-haired'. Samuels prefers 'kinky hair' or 'afro-hair', since 'woolly' comes from 18th-century racist ethnography.", "section": "sec-vlq0g9o2"}, {"id": "27ulqs02", "term": "'so more conclusively'", "definition": "Samuels' rendering of the phrase usually read 'but more importantly' in 2.104: circumcision solidifies, rather than outranks, the physical evidence.", "section": "sec-vlq0g9o2"}, {"id": "mueirrjj", "term": "The five sections", "definition": "I commentaries on 2.104; II race studies in Greco-Roman scholarship; III race in Classical Greece via CRT; IV Herodotus and Blacks; V implications.", "section": "sec-vlq0g9o2"}, {"id": "oywmcq1z", "term": "How and Wells", "definition": "Early commentators who called 2.104 'the usual Greek idea' but an exaggeration of 'brown' Egyptians, blaming 'negro slaves' in Memphis. Samuels' example of overt anti-Black racism.", "section": "sec-vlq0g9o2"}, {"id": "yv6q85c7", "term": "Armayor (1978)", "definition": "Used 2.104 to argue Herodotus never went to Egypt, treating his Black Egyptians as a literary tradition (Aeschylus, Pindar).", "section": "sec-vlq0g9o2"}, {"id": "c6omtfaf", "term": "Castillos (1984)", "definition": "Egyptologist who disputed Diop; claimed Herodotus' passages meant Ethiopians (a straw man, says Samuels) and assumed a 'white European' norm.", "section": "sec-vlq0g9o2"}, {"id": "7jrtblcm", "term": "Cheikh Anta Diop", "definition": "Scholar who asserted ancient Egypt's Blackness, citing Herodotus 2.57 and 2.104.", "section": "sec-vlq0g9o2"}, {"id": "t11he5x5", "term": "Alan B. Lloyd", "definition": "Egyptologist whose commentaries render melagchroes as 'bronzed to black' or 'swarthy'. Samuels calls his logic circular: Egyptians looked Black but weren't.", "section": "sec-vlq0g9o2"}, {"id": "v3k0xd63", "term": "Kenneth Dover (1998)", "definition": "Read melagchroes as 'dark-skinned', the deep tan of some Athenians, and called the Colchian description a mistaken tradition.", "section": "sec-vlq0g9o2"}, {"id": "87fbp0tc", "term": "Rosalind Thomas", "definition": "Accepts Herodotus saw Egyptians as Black but later says he argued mainly from custom and language; Samuels says she overlooks Blackness.", "section": "sec-vlq0g9o2"}, {"id": "e0y8kwj7", "term": "Frank Snowden", "definition": "First systematic study of Black people in antiquity (Blacks in Antiquity; Before Color Prejudice): argued the ancient world wasn't anti-Black and equated Blackness with Aithiopians.", "section": "sec-vlq0g9o2"}, {"id": "ik0ohpcy", "term": "Lloyd Thompson (1989)", "definition": "Romans and Blacks: found the Roman somatic norm was 'pale-brown', so Whiteness meant nothing to Roman identity.", "section": "sec-vlq0g9o2"}, {"id": "vy918q9v", "term": "Benjamin Isaac (2004)", "definition": "The Invention of Racism in Classical Antiquity: excluded Ethiopians, saying Blacks were a rare, expensive type of slave, and claimed Egyptian physical traits didn't interest Herodotus.", "section": "sec-vlq0g9o2"}, {"id": "xzkxq3qm", "term": "Denise McCoskey (2012)", "definition": "Race: Antiquity and Its Legacy: uses racial formation and CRT, but calls Egyptian Blackness in Herodotus 'minor', 'merely passing'; Samuels calls this White fragility.", "section": "sec-vlq0g9o2"}, {"id": "q4weqb93", "term": "Racial formation", "definition": "The idea (Omi and Winant; used by McCoskey) that race is a social construct shaped by social and historical forces.", "section": "sec-vlq0g9o2"}, {"id": "e8qkzg9k", "term": "Frank Martin (1984)", "definition": "Quoted: it's impossible to use facts to convince most Westerners taught to equate 'Negro' with inferiority that ancient Egyptians were Black.", "section": "sec-vlq0g9o2"}, {"id": "j5my4rme", "term": "Critical race theory (CRT)", "definition": "Movement begun in the US in the 1970s that addresses the permanence of racism, informed by the radical thought of people of color.", "section": "sec-vlq0g9o2"}, {"id": "45qhmahr", "term": "Barbara Fields: race vs. racism", "definition": "Race is a symmetrical mode of identification; racism is assigning people to an inferior category: asymmetrical, an imposition.", "section": "sec-vlq0g9o2"}, {"id": "a223ybm0", "term": "Tanned Greek Man", "definition": "The Greek somatic norm. Blackness was seen in relation to the tanned Greek man, not to Whiteness.", "section": "sec-vlq0g9o2"}, {"id": "6kydfwhy", "term": "Whiteness in Greek thought", "definition": "Per James Dee, a trait of Greek women or of barbarians north of the Alps, not of the Greek norm.", "section": "sec-vlq0g9o2"}, {"id": "f48vzi7d", "term": "Odysseus melagchroes", "definition": "Homer (Od. 16.175) calls Odysseus melagchroes; Samuels reads it 'tanned' for Greek men, not 'sunburnt' or 'dark'.", "section": "sec-vlq0g9o2"}, {"id": "et9fruu0", "term": "Aeschylus' 'sun-blackened race'", "definition": "His description of the Egyptians (Suppliants 154–155), linking Blackness to the sun.", "section": "sec-vlq0g9o2"}, {"id": "r2vf4n4s", "term": "Aristotelian Physiognomica", "definition": "Those too black are cowards (Egyptians, Aithiopians); those too white are cowards (women); the middle color favors bravery.", "section": "sec-vlq0g9o2"}, {"id": "exe6hj3w", "term": "Janiform vases", "definition": "Athenian two-faced vases pairing Greek women's faces with Black faces: both central 'others' to the tanned Greek man.", "section": "sec-vlq0g9o2"}, {"id": "pvez8zmr", "term": "Prejudice vs. racism (Herodotus)", "definition": "Herodotus had racial prejudices, but as a visitor, not a colonial ruler, they had no systematic effect on the peoples he described.", "section": "sec-vlq0g9o2"}, {"id": "adcctfr2", "term": "Herodotus 2.22", "definition": "Explains Aithiopian blackness (melanes) by the sun's heat: Greek climatic theory of racial difference.", "section": "sec-vlq0g9o2"}, {"id": "qcj12ohc", "term": "Herodotus 3.101", "definition": "Says Indians mate in public like cattle, are black like Aithiopians, and have black semen; Samuels' main example of gendered, sexualized anti-Black racism.", "section": "sec-vlq0g9o2"}, {"id": "mbyluaod", "term": "Herodotus 2.57", "definition": "The 'black dove' of Dodona is an Egyptian woman: the only explicit mention in the Histories of Egyptian women's Blackness.", "section": "sec-vlq0g9o2"}, {"id": "zvxrchya", "term": "Conclusion: timing of anti-Blackness", "definition": "Anti-Blackness predates the transatlantic slave trade and capitalism; Blackness preceded Whiteness. Snowden's 'before color prejudice' thesis is dismissible.", "section": "sec-vlq0g9o2"}, {"id": "9e2l8dfd", "term": "'Black races'", "definition": "Samuels' claim that there were several Black racial groups (e.g., Egyptians, Aithiopians), not one ethnically diverse Black race, in Greek thought.", "section": "sec-vlq0g9o2"}], "questions": [{"id": "wo9dvt5m", "prompt": "What did Psammetichos' experiment with two newborn children conclude?", "choices": ["The Phrygians are older than the Egyptians", "The Egyptians are the oldest people", "All languages descend from Greek", "The Ethiopians are the oldest people"], "answer": 0, "explanation": "The children said 'bekos', Phrygian for bread, so the Egyptians accepted that the Phrygians were older than themselves (2.2).", "difficulty": "easy", "section": "sec-jf8k2xgq"}, {"id": "aeqotljr", "prompt": "Who raised the children in Psammetichos' experiment, and how were they fed?", "choices": ["The king's own household, on honey", "Women whose tongues were cut out, on milk", "Priests, on bread", "A shepherd, on goats' milk"], "answer": 3, "explanation": "A shepherd kept them in a secluded hut and brought in goats to feed them. The tongue-cutting version is a 'silly' Greek story (2.2).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "nzykfi34", "prompt": "Herodotus calls the Egypt that the Greeks sail to…", "choices": ["the gift of the river", "the floor of the sea", "the mother of nations", "the land of the pharaohs"], "answer": 0, "explanation": "Land deposited by the Nile is 'the gift of the river' to the Egyptians (2.5).", "difficulty": "easy", "section": "sec-jf8k2xgq"}, {"id": "6qndpddt", "prompt": "Why does Herodotus think the Egyptian calendar is better than the Greek one?", "choices": ["Twelve 30-day months plus five extra days keep the seasons in place", "It has thirteen months", "It follows the moon exactly", "It starts with the Nile flood"], "answer": 0, "explanation": "The Greeks add an extra month every other year; the Egyptians add five days a year, so their seasons return at the same time (2.4).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "v5cxk5ax", "prompt": "What evidence does Herodotus give that Egypt was built up from river mud?", "choices": ["Fish fossils in the temples", "Seashells on the mountains and salt eating at the pyramids", "Old maps kept by the priests", "Greek sailors' logbooks"], "answer": 1, "explanation": "He cites the Delta jutting out, seashells on the mountains, salt damaging the pyramids, and the black crumbly soil (2.12).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "goh3n6wp", "prompt": "What did the Egyptians predict would happen to the Greeks someday?", "choices": ["Their soil would turn to salt", "The Persians would conquer them", "Their rivers would flood their cities", "A drought would starve them, since their crops depend on rain from Zeus"], "answer": 3, "explanation": "Greek land is watered only by rain, so if Zeus sends drought instead the Greeks would starve. Herodotus warns Egyptians below Memphis could face the same if their land keeps rising (2.13–2.14).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "fd31iv2b", "prompt": "How do farmers below Memphis plant and thresh their grain, according to Herodotus?", "choices": ["With oxen and plows", "Slaves dig with hoes", "They throw seed into the flood", "They let pigs tread the seed in and thresh it"], "answer": 3, "explanation": "When the river recedes each man sows his field and turns pigs onto it to tread the seed in, then threshes with pigs too (2.14).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "lq0cdfvm", "prompt": "Which view of Egypt does Herodotus reject?", "choices": ["That Egypt reaches to Elephantine", "That Egypt is all land the Nile floods", "The Ionian view that Egypt is only the Delta", "The oracle of Ammon's definition"], "answer": 2, "explanation": "If Egypt were just the recently formed Delta, the Egyptians couldn't have thought themselves the first people. He defines Egypt as land inhabited by Egyptians (2.15–2.17).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "2uw92nw5", "prompt": "Why did the people of Mareia and Apis ask the oracle of Ammon to declare them non-Egyptian?", "choices": ["To marry Libyans", "So they could eat cow meat", "To avoid paying taxes", "To avoid military service"], "answer": 1, "explanation": "They disliked the rule against eating cows. The oracle said all who live below Elephantine and drink the Nile's water are Egyptians (2.18).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "hjf3875b", "prompt": "When does the Nile begin to flood, according to Herodotus?", "choices": ["In midwinter", "After the Etesian winds stop", "At the spring equinox", "At the summer solstice, for about 100 days"], "answer": 3, "explanation": "It floods from the summer solstice for 100 days, then stays low all winter, the opposite of other rivers (2.19).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "ppwf5skw", "prompt": "How does Herodotus refute the Etesian winds theory of the flood?", "choices": ["The Nile floods even when the Etesians don't blow, and other rivers facing those winds don't flood", "The Etesians only blow in winter", "Priests told him it was false", "The winds blow from the south"], "answer": 0, "explanation": "He gives both arguments in 2.20.", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "wpy43aav", "prompt": "Which flood theory does Herodotus call the most plausible but most wrong?", "choices": ["The sun", "Melting snow", "The Etesian winds", "The Nile flows from Ocean"], "answer": 1, "explanation": "Snow is impossible: the Nile comes from the hottest lands, where winds are warm, there's no rain or ice, and people are black from the sun (2.22).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "mq4guatt", "prompt": "What is Herodotus' own explanation for why the Nile runs low in winter?", "choices": ["The Etesian winds push it back", "The winter sun over Libya draws the Nile's water up", "Snow freezes its sources", "Winter rain is caught in lakes"], "answer": 1, "explanation": "Storms drive the sun south in winter; it draws water from the Nile, which alone suffers evaporation in winter (2.24–2.25).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "nw1vmce7", "prompt": "Who claimed to know the sources of the Nile, and what did Herodotus think?", "choices": ["A scribe of Athena's treasury at Sais; Herodotus thought he was joking", "The Nasamonians; he called them liars", "Priests at Memphis; he believed them", "Etearchos; he agreed completely"], "answer": 0, "explanation": "The scribe spoke of bottomless springs between Krophi and Mophi (2.28).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "wggnchll", "prompt": "How far up the Nile does Herodotus say he traveled to see for himself?", "choices": ["Elephantine", "Thebes", "Memphis", "Meroe"], "answer": 0, "explanation": "He went as far as Elephantine; everything beyond came from hearsay (2.29).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "t7jbgsyt", "prompt": "Why did the 240,000 'Deserters' leave Psammetichos for Ethiopia?", "choices": ["Psammetichos took their land", "No one relieved them from garrison duty for three years", "They were defeated in battle", "An oracle ordered them"], "answer": 1, "explanation": "After three years without relief they revolted and went to Ethiopia, where they made the Ethiopians more civilized (2.30).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "stptlvvk", "prompt": "What did the Nasamonian youths find beyond the Libyan desert?", "choices": ["A city of giants by a lake", "The source of the Nile in two mountains", "Small black-skinned people by a river with crocodiles flowing east", "A Greek colony"], "answer": 2, "explanation": "Herodotus and Etearchos think the river was the Nile (2.32–2.33).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "qkha3nzz", "prompt": "Which river does Herodotus say mirrors the Nile in length and course?", "choices": ["Phasis", "Ister (Danube)", "Achelous", "Maeander"], "answer": 1, "explanation": "The Ister cuts Europe in half just as the Nile cuts Libya in half (2.33–2.34).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "m2wltbg5", "prompt": "Which of these is one of the Egyptian 'opposite' customs Herodotus lists?", "choices": ["Men sell in the market, women weave", "Women sell in the market, men weave at home", "Only slaves go to market", "Both men and women weave"], "answer": 1, "explanation": "Herodotus says Egyptian customs are mostly the opposite of others' (2.35).", "difficulty": "easy", "section": "sec-jf8k2xgq"}, {"id": "nqh8yy9g", "prompt": "How do Egyptian men and women carry loads, according to Herodotus?", "choices": ["Men on shoulders, women on heads", "Men on heads, women on shoulders", "Both on their backs", "Only donkeys carry loads"], "answer": 1, "explanation": "Another reversal from 2.35.", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "a8eygax8", "prompt": "What do Egyptians do with their hair when someone dies?", "choices": ["Dye it black", "Cut it and burn it", "Shave it off", "Let it grow on head and chin"], "answer": 3, "explanation": "Elsewhere mourners cut their hair; Egyptians, who are usually shaved, let it grow (2.36).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "q61t6yod", "prompt": "Which food may Egyptian priests NOT eat?", "choices": ["Bread", "Beef", "Fish", "Goose"], "answer": 2, "explanation": "Priests receive beef, goose and wine but may not even taste fish, and can't stand the sight of beans (2.37).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "48x5ykvl", "prompt": "What makes a bull unclean for sacrifice?", "choices": ["Having been born at night", "A single black hair", "A white spot on its tail", "Being older than two"], "answer": 1, "explanation": "One black hair disqualifies it; a clean bull is sealed and marked, and sacrificing an unmarked one is punished by death (2.38).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "9o3k6f6d", "prompt": "What happens to the head of a sacrificed bull?", "choices": ["The priests eat it", "It is cursed, then sold to Greeks or thrown into the river", "It is placed on the altar", "It is buried in the temple"], "answer": 1, "explanation": "The curses send any coming evil onto the head; no Egyptian will eat an animal's head (2.39).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "y9xqr4yy", "prompt": "Why won't an Egyptian kiss a Greek man or use his knife?", "choices": ["Greeks eat cows, which are sacred to Isis", "Greeks don't shave", "Greeks eat pigs", "Greeks are uncircumcised"], "answer": 0, "explanation": "Cows are sacred to Isis, so Egyptians avoid Greeks' knives, skewers and pots (2.41).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "sjud0tqq", "prompt": "Why do the Thebans not sacrifice rams?", "choices": ["An oracle forbade it", "Rams are too expensive", "Zeus showed himself to Herakles wearing a ram's fleece and head", "Rams belong to Isis"], "answer": 2, "explanation": "So the Egyptians make Zeus (Ammon) ram-headed and treat rams as sacred (2.42).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "d76j3171", "prompt": "Why did Herodotus sail to Tyre and Thasos?", "choices": ["To find the Nile's source", "To learn how old Herakles is", "To see the Deserters", "To buy papyrus"], "answer": 1, "explanation": "Both sanctuaries of Herakles were far older than the Greek Herakles son of Amphitryon (2.44).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "vtgljni7", "prompt": "Why does Herodotus reject the Greek story that Egyptians tried to sacrifice Herakles?", "choices": ["Egyptians may not even sacrifice most animals, let alone humans", "Herakles was Egyptian", "Herakles never went to Egypt", "The story came from Persians"], "answer": 0, "explanation": "He also asks how one man could kill thousands at once (2.45).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "uphl7p9f", "prompt": "Which Egyptians are barred from every sanctuary?", "choices": ["Scribes", "Fishermen", "Swineherds", "Foreigners"], "answer": 2, "explanation": "Pigs are unclean; swineherds can't enter temples and must marry among themselves (2.47).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "ikr0nvbf", "prompt": "Who taught the Greeks the name of Dionysos and the phallic procession?", "choices": ["Melampous", "Homer", "Kadmos", "Pythagoras"], "answer": 0, "explanation": "Melampous learned it from Egypt, probably through Kadmos of Tyre (2.49).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "gf6t325j", "prompt": "Where does Herodotus say Poseidon's name came to the Greeks from?", "choices": ["Egypt", "Phoenicia", "Libya", "Thrace"], "answer": 2, "explanation": "The Libyans alone have always honored Poseidon (2.50).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "98t2o62w", "prompt": "From whom did the Athenians learn to make statues of Hermes with an erect phallus?", "choices": ["The Pelasgians", "The Libyans", "The Egyptians", "The Phoenicians"], "answer": 0, "explanation": "The Pelasgians, who also lived on Samothrace (2.51).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "woyhi3c6", "prompt": "What did the oracle at Dodona tell the Pelasgians about the gods' names from Egypt?", "choices": ["Use only Zeus", "Reject them", "Ask Ammon", "Use them"], "answer": 3, "explanation": "Dodona, thought to be the oldest Greek oracle, approved them (2.52).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "955f27rf", "prompt": "According to Herodotus, who gave the Greeks the theogony and the gods' appearances?", "choices": ["Orpheus and Musaeus", "The Pelasgians", "Hesiod and Homer, no more than 400 years before his time", "Melampous"], "answer": 2, "explanation": "He believes the poets said to be earlier actually lived later (2.53).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "s8unja2g", "prompt": "In the Dodona priestesses' story, what founded the oracles of Dodona and Ammon?", "choices": ["Two eagles from Zeus", "Two Phoenician priests", "Two black doves from Egyptian Thebes", "Herakles"], "answer": 2, "explanation": "One dove went to Dodona and spoke with a human voice; the other went to Libya (2.55).", "difficulty": "easy", "section": "sec-jf8k2xgq"}, {"id": "n8j40smp", "prompt": "How does Herodotus explain the 'dove' that spoke at Dodona?", "choices": ["It was a real talking bird", "It was a priest in disguise", "It was a Greek poetic image only", "It was a foreign woman whose speech sounded like a bird's, and 'black' shows she was Egyptian"], "answer": 3, "explanation": "He thinks she later learned Greek and 'spoke with a human voice' (2.57).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "os82evqb", "prompt": "Which is Egypt's most popular festival?", "choices": ["Artemis at Boubastis", "Ares at Papremis", "Isis at Bousiris", "Athena at Sais"], "answer": 0, "explanation": "Up to 700,000 men and women gather at Boubastis (2.59–2.60).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "wtvze2pf", "prompt": "What happens at the festival of Ares at Papremis?", "choices": ["A club fight at the sanctuary entrance", "A boat race", "Lamps burn all night", "Women mock other towns from barges"], "answer": 0, "explanation": "Priests and vow-fulfillers fight with wooden clubs; Herodotus thinks many die, though the Egyptians deny it (2.63).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "w5ioem82", "prompt": "The Feast of the Burning Lamps is held at…", "choices": ["Bouto", "Memphis", "Sais", "Heliopolis"], "answer": 2, "explanation": "The festival at Sais honors Athena; lamps burn all night all over Egypt (2.62).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "wnegt59p", "prompt": "What religious rule do Egyptians and Greeks share, according to Herodotus?", "choices": ["No eating beans", "No festivals at night", "No sacrifice of goats", "No intercourse in sanctuaries, or entering unwashed after it"], "answer": 3, "explanation": "Most other peoples, he says, don't keep this rule (2.64).", "difficulty": "medium", "section": "sec-jf8k2xgq"}, {"id": "xsh58bhf", "prompt": "What changes in Herodotus' method at 2.99?", "choices": ["He starts quoting Homer", "He stops reporting his own observation and reports what the Egyptians told him", "He begins listing distances", "He switches to Persian sources"], "answer": 1, "explanation": "Before 2.99 it was his own observation, judgment and research; now he reports the Egyptians' words, sometimes adding his own observations.", "difficulty": "easy", "section": "sec-my15bzm2"}, {"id": "7jrwsny9", "prompt": "How did Min make room for Memphis?", "choices": ["He drained Lake Moeris", "He built on an island", "He cut down a forest", "He dammed the Nile south of the site and moved it into a new channel"], "answer": 3, "explanation": "The Persians still reinforce that bend each year so it won't flood Memphis (2.99).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "ed6udg1b", "prompt": "Of the 330 kings after Min, how many were Ethiopians?", "choices": ["Eighteen", "None", "Thirty", "One"], "answer": 0, "explanation": "All were Egyptian men except 18 Ethiopians and one native woman, Nitokris (2.100).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "47ryfcwq", "prompt": "How did Nitokris take revenge for her brother?", "choices": ["She exiled them to Ethiopia", "She poisoned the guilty at a feast", "She burned their houses", "She flooded an underground banquet hall through a secret conduit"], "answer": 3, "explanation": "Afterward she threw herself into a chamber full of ashes to escape revenge (2.100).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "tw5mw24r", "prompt": "What did Sesostris add to pillars in lands that surrendered without a fight?", "choices": ["Nothing at all", "A chained captive", "A broken spear", "An image of female genitals"], "answer": 3, "explanation": "It publicized their cowardice; brave peoples got only his name, land and victory (2.102).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "sjwav9zn", "prompt": "How far into Europe did Sesostris go, in Herodotus' view?", "choices": ["Greece", "Scythia and Thrace", "He never crossed into Europe", "Italy"], "answer": 1, "explanation": "No pillars appear beyond the Scythians and Thracians (2.103).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "k9q5lkti", "prompt": "Which people does Herodotus argue are descendants of Sesostris' army?", "choices": ["The Phoenicians", "The Colchians", "The Scythians", "The Ionians"], "answer": 1, "explanation": "Soldiers stayed near the River Phasis; he says the Colchians remember the Egyptians more than vice versa (2.103–2.104).", "difficulty": "easy", "section": "sec-my15bzm2"}, {"id": "g5d9po1w", "prompt": "In 2.104, which evidence does Herodotus say proves nothing on its own?", "choices": ["Being black-skinned and woolly-haired, since others look like this too", "Their language", "Their linen", "Circumcision"], "answer": 0, "explanation": "He leans further on circumcision, practiced from the earliest times only by Colchians, Egyptians and Ethiopians (2.104).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "dgy7vhlf", "prompt": "Which peoples say they learned circumcision from the Egyptians?", "choices": ["The Scythians and Thracians", "The Persians and Medes", "The Ionians and Lydians", "The Phoenicians and the Syrians of Palestine"], "answer": 3, "explanation": "Syrians near the Thermodon and Parthenios say they learned it recently from the Colchians (2.104).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "vnpc9dm3", "prompt": "What do the Greeks call linen from Colchis?", "choices": ["Egyptian", "Phasian", "Byssus", "Sardonian"], "answer": 3, "explanation": "Only Colchians and Egyptians make linen the same way (2.105).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "5zeu3xvg", "prompt": "Who do some people wrongly think the Ionian rock reliefs show?", "choices": ["Memnon", "Cyrus", "Croesus", "Darius"], "answer": 0, "explanation": "Herodotus says records show they are the work of Sesostris (2.106).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "tlq4t08c", "prompt": "How did Sesostris escape his brother's fire at Daphnai?", "choices": ["His wife had two of their six children laid across the fire as a bridge", "Rain put it out", "His soldiers broke down the walls", "He dug a tunnel"], "answer": 0, "explanation": "Two children died; the rest escaped with him (2.107).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "vorsbyt4", "prompt": "What unexpected result came from Sesostris' canals?", "choices": ["Egypt could no longer use horses and chariots", "Lake Moeris dried up", "The Nile stopped flooding", "The Delta shrank"], "answer": 0, "explanation": "The canals cut up the land everywhere (2.108).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "jrtgzgwu", "prompt": "Where does Herodotus think the Greeks got geometry and the sundial?", "choices": ["Both from Babylon", "Geometry from Egypt, the sundial and twelve divisions of the day from Babylon", "Both from Egypt", "Geometry from Phoenicia, the sundial from Egypt"], "answer": 1, "explanation": "Geometry grew from measuring land the river took from taxed plots (2.109).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "qnndhgs5", "prompt": "Why did the priest of Hephaistos refuse to let Darius put up a statue?", "choices": ["Darius had burned a temple", "Darius was a foreigner", "Darius had not conquered the Scythians as Sesostris had", "The space was sacred to Ptah"], "answer": 2, "explanation": "Darius, they say, agreed (2.110).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "ieku0v2k", "prompt": "How was Pheros blinded?", "choices": ["Thieves attacked him", "He threw a spear into the flooding Nile", "An oracle cursed his father", "He looked at the sun"], "answer": 1, "explanation": "His reckless act brought ten years of blindness until the oracle at Bouto gave the cure (2.111).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "l94e9t0s", "prompt": "What did Pheros do after he was cured?", "choices": ["Burned the women in Red Soil, except the one who cured him, whom he married", "Freed all the women", "Built a pyramid", "Abdicated"], "answer": 0, "explanation": "He also gave two huge stone obelisks to the sanctuary of Helios (2.111).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "k3yrwa9z", "prompt": "Why does Herodotus think the 'Foreign Aphrodite' sanctuary at Memphis is really Helen's?", "choices": ["It has her name carved on it", "The priests said so", "Homer says so", "Helen stayed with Proteus, and no other Aphrodite is called 'Foreign'"], "answer": 3, "explanation": "It sits in Proteus' precinct in the Camp of the Tyrians (2.112).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "m6aaso0t", "prompt": "Who turned Alexandros in to the Egyptians?", "choices": ["His own servants, who fled to the sanctuary of Herakles", "Menelaos", "Phoenician sailors", "Helen"], "answer": 0, "explanation": "They took asylum and told the priests and the guard Thonis everything (2.113).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "rjeu1zjv", "prompt": "What was Proteus' decision about Alexandros?", "choices": ["Execute him", "Let him live but keep Helen and the property for Menelaos, and make him leave in three days", "Enslave him", "Send him to Troy with Helen"], "answer": 1, "explanation": "Proteus won't kill strangers driven to Egypt by the winds (2.115).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "nnczb0r8", "prompt": "What does Herodotus conclude about the poem called the Cypria?", "choices": ["Homer wrote it", "It wasn't by Homer, because it has Alexandros reach Troy in three days with fair winds", "It is older than the Iliad", "It agrees with the Egyptian version"], "answer": 1, "explanation": "In the Iliad Alexandros is driven off course, reaching Sidon (2.116–2.117).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "d619wmxn", "prompt": "According to the priests, why did the Greeks keep besieging Troy?", "choices": ["Menelaos refused peace", "They wanted its gold", "They thought the Trojans were mocking them by saying Helen was in Egypt", "An oracle ordered them to"], "answer": 2, "explanation": "After taking Troy and not finding Helen, they sent Menelaos to Proteus (2.118).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "94relea5", "prompt": "What did Menelaos do in Egypt that made the Egyptians hate him?", "choices": ["Sacrificed two local children for fair winds", "Burned a temple", "Kidnapped a priestess", "Stole Proteus' treasure"], "answer": 0, "explanation": "He then fled to Libya, hunted (2.119).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "gtvi7fvp", "prompt": "What is Herodotus' own lesson from the Trojan War?", "choices": ["Fate cannot be avoided", "Love conquers all", "Great injustices bring great retribution from the gods", "Never trust Egyptians"], "answer": 2, "explanation": "He argues Priam would surely have given Helen back if she were in Troy (2.120).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "34bf20ni", "prompt": "What are Rhampsinitos' two statues called?", "choices": ["Summer and Winter", "Day and Night", "Isis and Osiris", "Upper and Lower Egypt"], "answer": 0, "explanation": "'Summer' is honored; 'Winter' is treated the opposite way (2.121).", "difficulty": "easy", "section": "sec-my15bzm2"}, {"id": "c6mht5zv", "prompt": "How did the thieves get into Rhampsinitos' treasury?", "choices": ["Through a removable stone their father built in", "With a copied key", "Through the roof", "By bribing the guards"], "answer": 0, "explanation": "The seals stayed intact, which baffled the king (2.121).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "86rd503n", "prompt": "Why did the surviving thief cut off his brother's head?", "choices": ["Out of anger", "An oracle demanded it", "So the body couldn't be identified and ruin them both", "To show the king"], "answer": 2, "explanation": "His trapped brother asked him to (2.121).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "0pkma5l1", "prompt": "How did the thief get his brother's body back from the guards?", "choices": ["Disguised himself as a priest", "Spilled wineskins, got them drunk, and shaved their right cheeks", "Dug a tunnel", "Bribed them with silver"], "answer": 1, "explanation": "His mother had threatened to turn him in if he didn't (2.121).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "2jnhltzs", "prompt": "How did the thief escape the king's daughter?", "choices": ["He climbed out a window", "He gave her a dead man's arm to hold in the dark", "He bribed her", "He wore a disguise"], "answer": 1, "explanation": "The king then pardoned him and gave him his daughter as wife (2.121).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "acdf6hgy", "prompt": "What did Rhampsinitos bring back from playing dice with Demeter?", "choices": ["The key to his treasury", "A golden handkerchief", "A wolf", "A silver cup"], "answer": 1, "explanation": "A festival marks his return (2.122).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "j944ntg1", "prompt": "In the festival of Demeter, who leads the blindfolded priest to the sanctuary?", "choices": ["A sacred bull", "The king", "Two wolves", "Two priestesses"], "answer": 2, "explanation": "Herodotus adds that he records what he's told, for anyone who finds it credible (2.122–2.123).", "difficulty": "medium", "section": "sec-my15bzm2"}, {"id": "adtywwu4", "prompt": "What method does Samuels use to analyze Herodotus' view of Blackness?", "choices": ["Comparative mythology", "Linguistic statistics", "Critical race theory", "Archaeological survey"], "answer": 2, "explanation": "The subtitle is 'A Critical Race Theory Analysis'.", "difficulty": "easy", "section": "sec-vlq0g9o2"}, {"id": "eg3vfvc3", "prompt": "What is Samuels' main claim?", "choices": ["Egyptians were not described physically by Herodotus", "Greeks had no idea of race", "Herodotus never visited Egypt", "Blackness was a factor in Greek racial thought and significant in Herodotus' ethnography"], "answer": 3, "explanation": "This runs against the consensus in Greco-Roman studies.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "hkdkolld", "prompt": "Why does Samuels say Herodotus' view of Blackness is usually only discussed through 2.104?", "choices": ["Because Herodotus said it was important", "It's the only passage on Egypt", "Because of the modern debate over ancient Egyptian racial identity", "Because 2.104 was recently found"], "answer": 2, "explanation": "Commentators focused on defending their views about whether the Egyptians were Black.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "cbjoa142", "prompt": "How does Samuels translate oulotriches for Black groups?", "choices": ["Curly-haired", "Woolly-haired", "Long-haired", "Kinky hair or afro-hair"], "answer": 3, "explanation": "'Woolly' comes from 18th-century European ethnography that treated Black hair as animal-like.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "nnqwcuqc", "prompt": "In Samuels' translation of 2.104, what does the phrase usually read as 'but more importantly' become?", "choices": ["'but less certainly'", "'so more conclusively'", "'and therefore'", "'as everyone knows'"], "answer": 1, "explanation": "Circumcision is solidifying evidence, so Herodotus used both physical appearance and customs.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "lofa3i58", "prompt": "Why, per Samuels, did Herodotus add circumcision as evidence in 2.104?", "choices": ["Physical traits didn't matter to him", "Other Black groups looked similar, so he needed further evidence", "His sources insisted", "He doubted the Colchians were black"], "answer": 1, "explanation": "There were multiple Black groups in the Greek world, so appearance alone couldn't single out Egyptians.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "br8qivku", "prompt": "How did How and Wells explain Herodotus' description of Egyptians?", "choices": ["He was confused by 'negro slaves' he saw in Memphis", "He was quoting Homer", "He meant Ethiopians", "He never went to Egypt"], "answer": 0, "explanation": "Samuels calls this an anti-Black stereotype and an example of overt racism in early commentaries.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "qfiack06", "prompt": "What did Armayor use 2.104 to argue?", "choices": ["Herodotus never went to Egypt", "Egyptians were Greek", "Colchians were Scythians", "Herodotus was a racist"], "answer": 0, "explanation": "He treated Black Egyptians as a literary tradition; Samuels says he gives no motive for such a tradition.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "lidk7264", "prompt": "Why does Samuels call Castillos' criticism of Diop a straw man?", "choices": ["Castillos agreed with Diop", "Diop cited 2.57 and 2.104, which clearly refer to Egyptians, not Ethiopians", "Diop never cited Herodotus", "Diop was not an Egyptologist"], "answer": 1, "explanation": "Castillos assumed Aithiopians were the only Blacks in Greek eyes.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "u2m1lbok", "prompt": "What does Samuels call Lloyd's reasoning about Egyptian appearance?", "choices": ["Sound but incomplete", "Too accepting of Herodotus", "Circular: Egyptians looked like Black people but weren't Black", "Based on new evidence"], "answer": 2, "explanation": "Lloyd concedes the features would 'certainly' be found among Egyptians yet denies they were Black.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "v8frurw3", "prompt": "Which passage does Samuels say Lloyd ignored that shows Herodotus' interest in Egyptian appearance?", "choices": ["2.57", "1.1", "3.38", "7.70"], "answer": 0, "explanation": "Lloyd said Herodotus discussed Egyptian physical traits only at 2.104.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "xgjeimzb", "prompt": "How did Dover read melagchroes for the Colchians?", "choices": ["As 'dark-skinned', the deep tan of some Athenians", "As black-skinned", "As a poetic metaphor", "As bronze-colored armor"], "answer": 0, "explanation": "Samuels says this assumes Athenian identity was White.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "qrej69n8", "prompt": "What does Samuels criticize in Rosalind Thomas' reading?", "choices": ["She calls Herodotus a liar", "She mistranslates circumcision", "She denies Herodotus visited Egypt", "She says the Colchian argument rests mainly on custom and language, overlooking Blackness"], "answer": 3, "explanation": "Herodotus says the physical similarities started his conjecture.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "gllkjjc7", "prompt": "What was Frank Snowden's main contention?", "choices": ["Herodotus was unreliable", "Romans invented racism", "The Greco-Roman world wasn't anti-Black like the modern world", "Egyptians were Black"], "answer": 2, "explanation": "Samuels says Greek texts show clear anti-Black prejudice, and Snowden wrongly made Blackness exclusive to Aithiopians.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "lcz6jfd6", "prompt": "What did Lloyd Thompson identify as the Roman somatic norm?", "choices": ["Pale-brown", "White", "Olive", "Tanned"], "answer": 0, "explanation": "So Whiteness had no socio-cultural significance for Roman identity.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "mh2q1cwy", "prompt": "Why does Benjamin Isaac leave Ethiopians out of his study?", "choices": ["The sources are lost", "He says they were a rare slave type, partly mythical, with little impact", "They didn't exist", "He covers them in another book"], "answer": 1, "explanation": "Samuels calls tying the Black presence in Athens only to servitude a stereotype.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "ldg96qqt", "prompt": "How does McCoskey describe Herodotus' references to Egyptian Blackness?", "choices": ["Fabricated", "Central", "Mistranslated", "'Minor' and 'merely passing'"], "answer": 3, "explanation": "She also calls Afrocentric claims a 'dangerous racial essentialism'; Samuels calls her argument a reflex of White fragility.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "vm2dejhe", "prompt": "What does Samuels credit McCoskey for?", "choices": ["Proving Egyptians were Black", "Translating Herodotus", "Using racial formation and CRT as a framework for race in antiquity", "Discovering the Janiform vases"], "answer": 2, "explanation": "But she doesn't contextualize Blackness within Greek or Roman racial formation.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "3d7rp5gk", "prompt": "Per Barbara Fields, how does racism differ from race?", "choices": ["Race is biological, racism cultural", "Race is a symmetrical identification; racism assigns people to an inferior category, an asymmetrical imposition", "Racism is symmetrical, race is not", "They are the same"], "answer": 1, "explanation": "Targets of racism can only challenge or navigate its obstacles.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "diggulqo", "prompt": "What was the Greek somatic norm, according to Samuels?", "choices": ["Pale-brown", "Bronze", "White", "The tanned Greek man"], "answer": 3, "explanation": "Blackness was seen in relation to the tanned Greek man, not Whiteness.", "difficulty": "easy", "section": "sec-vlq0g9o2"}, {"id": "eybdurz5", "prompt": "According to James Dee, whom did Greeks associate with Whiteness?", "choices": ["Greek men", "Egyptians", "Greek women or barbarians north of the Alps", "Persians"], "answer": 2, "explanation": "So the Greek norm can't have been White.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "vdfcrexp", "prompt": "How should melagchroes be translated when Homer uses it for Odysseus?", "choices": ["Black", "Dark", "Sunburnt", "Tanned"], "answer": 3, "explanation": "'He was tanned in color again'; 'tan' applies only to Greek men.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "jfa2qzyi", "prompt": "What does the Aristotelian Physiognomica say about color and bravery?", "choices": ["Darker people are braver", "Only white is brave", "Too black (Egyptians, Aithiopians) and too white (women) are cowards; the middle color favors bravery", "Color has nothing to do with bravery"], "answer": 2, "explanation": "Samuels calls this an indisputable example of anti-Blackness in Greek thought.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "dvjla0pa", "prompt": "What do the Janiform vases pair together?", "choices": ["Gods and heroes", "Greek men and Persians", "Greek women and Black people", "Egyptians and Aithiopians"], "answer": 2, "explanation": "Both were central 'others' to the tanned Greek man.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "vn6za61m", "prompt": "Why does Samuels distinguish Herodotus' racial prejudice from racism?", "choices": ["As a visitor, not an imperial or colonial ruler, his prejudice had no systematic effect", "Racism didn't exist yet", "He only wrote about Greeks", "Herodotus had none"], "answer": 0, "explanation": "It may still reflect racism in the Greek city-states where he lived.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "zudb0poe", "prompt": "How does Herodotus explain Aithiopian blackness in 2.22?", "choices": ["Ancestry from Egypt", "A curse", "The heat of the sun", "Diet"], "answer": 2, "explanation": "This matches Greek climatic theory.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "7i38qcjc", "prompt": "Which passage is Samuels' main example of gendered anti-Black racism in Herodotus?", "choices": ["1.1", "2.35", "4.42", "3.101"], "answer": 3, "explanation": "Indians and Aithiopians are said to mate in public like cattle and have black semen.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "crbrq121", "prompt": "What does Samuels say the 'black dove' of 2.57 shows?", "choices": ["Herodotus took an Egyptian Black woman to have founded Dodona's oracle; melas connotes Blackness", "Doves were sacred in Egypt", "The story is Phoenician", "Herodotus disliked Egyptians"], "answer": 0, "explanation": "It's the only explicit mention of Egyptian women's Blackness in the Histories.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "af3888d4", "prompt": "According to Samuels' conclusion, when did Western anti-Blackness begin?", "choices": ["With Rome", "Before it: Herodotus shows anti-Black prejudice in antiquity", "With the transatlantic slave trade", "In the 19th century"], "answer": 1, "explanation": "Blackness preceded Whiteness, and Snowden's 'before color prejudice' thesis is dismissible.", "difficulty": "medium", "section": "sec-vlq0g9o2"}, {"id": "hlosuy1l", "prompt": "Instead of one ethnically diverse Black race, Samuels says Greek thought had…", "choices": ["a White/Black binary", "no idea of Blackness", "several Black races, such as Egyptians and Aithiopians", "only Aithiopian Blacks"], "answer": 2, "explanation": "Herodotus' mention of straight-haired Asiatic Aithiopians shows there was no 'True Black' type.", "difficulty": "medium", "section": "sec-vlq0g9o2"}], "entries": []}$j$::jsonb, $j${"modes": ["learn", "flashcards", "quiz", "match", "rush"], "questionCount": 10, "rushSeconds": 60, "matchPairs": 6, "shuffle": true, "showExplanations": true, "requireFlashcardsFirst": false, "v": 2}$j$::jsonb, true);
end $$;
